          key={view}
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -8 }}
          transition={{ duration: 0.18 }}
        >
          {view === 'standings' && <StandingsTable rows={standings} config={config} />}
          {view === 'teams' && <TeamGrid rows={standings} config={config} />}
          {view === 'players' && (
            <PlayerLeaders
              players={players}
              teams={teams}
              config={config}
              onPick={setViewingPlayer}
            />
