/**
 * staffFallback — synthetic placeholders for missing staff data.
 *
 * NBA staff comes from a curated gist. International clubs (Endesa,
 * Euroleague, …) have no equivalent dataset, so we synthesize coach + GM
 * records on demand, drawing names from the bundled ZenGM name pool with
 * country-aware probability:
 *   - Local hire (~55%): name from the club's home country
 *   - Foreign hire (~45%): name from the European top-coaching pool
 *     (Serbia, Lithuania, Greece, Italy, USA, Croatia, Turkey, France, …)
 *
 * Everything is deterministic per team seed so the same save reloads
 * with the same staff names. Generated records can be either consumed
 * on-demand or merged into `state.staff` after the gist lazy-load
 * (mirrors the fictional-league pattern).
 */
import type { NBATeam, NameData, StaffData, StaffMember, GameState } from '../../types';
import { DEFAULT_GM_ATTRIBUTES, type GMAttributes } from './gmAttributes';
import { getNameData } from '../../data/nameDataFetcher';
import { getTeamCountry } from '../../utils/teamCountry';

export interface PlaceholderGM {
  name: string;
  position: string;
  team: string;
  attributes: GMAttributes;
  playerPortraitUrl: string;
  nationality: string;
  isPlaceholder: true;
}

export interface PlaceholderCoach {
  name: string;
  position: string;
  team: string;
  systemBias?: string;
  reputation?: number;
  nationality: string;
  bornYear: number;
  yearsWithTeam: number;
  careerStartYear: number;
  isPlaceholder: true;
}

// European basketball coach origin pool (real-world distribution).
const FOREIGN_COACH_POOL = [
  'Serbia', 'Lithuania', 'Greece', 'Italy', 'United States', 'Croatia',
  'Turkey', 'France', 'Slovenia', 'Spain',
];

const LOCAL_HIRE_PROBABILITY = 0.55;

function seedFromTeam(team: NBATeam | { id: number; tid?: number; name: string }): number {
  const id = (team as any).id ?? (team as any).tid ?? 0;
  const key = `${id}-${team.name}`;
  let h = 0;
  for (let i = 0; i < key.length; i++) h = (Math.imul(31, h) + key.charCodeAt(i)) | 0;
  return Math.abs(h);
}

function fmtTeamLabel(team: { region?: string; name: string }): string {
  return team.region && !team.name.includes(team.region)
    ? `${team.region} ${team.name}`
    : team.name;
}

function rngFromSeed(seed: number): () => number {
  let s = seed || 1;
  return () => {
    s = (s * 16807) % 2147483647;
    return s / 2147483647;
  };
}

function pickCountry(homeCountry: string, rng: () => number): string {
  if (!homeCountry) return FOREIGN_COACH_POOL[Math.floor(rng() * FOREIGN_COACH_POOL.length)];
  if (rng() < LOCAL_HIRE_PROBABILITY) return homeCountry;
  return FOREIGN_COACH_POOL[Math.floor(rng() * FOREIGN_COACH_POOL.length)];
}

function pickNameFromCountry(country: string, nameData: NameData, rng: () => number): string {
  const c = nameData.countries?.[country] ?? nameData.countries?.['USA'];
  const firstPool = Object.keys(c?.first ?? {});
  const lastPool = Object.keys(c?.last ?? {});
  if (!firstPool.length || !lastPool.length) return 'Unknown Coach';
  const first = firstPool[Math.floor(rng() * firstPool.length)];
  const last = lastPool[Math.floor(rng() * lastPool.length)];
  return `${first} ${last}`;
}

export function makePlaceholderCoach(
  team: NBATeam | { id?: number; tid?: number; name: string; region?: string; logoUrl?: string },
  opts?: { country?: string; nameData?: NameData },
): PlaceholderCoach {
  const seed = seedFromTeam(team as any);
  const rng = rngFromSeed(seed);
  const nameData = opts?.nameData ?? getNameData();
  const homeCountry = opts?.country ?? '';
  const nationality = pickCountry(homeCountry, rng);
  const name = pickNameFromCountry(nationality, nameData, rng);
  const tenureRoll = rng();
  const yearsWithTeam = tenureRoll < 0.5 ? 1 : tenureRoll < 0.85 ? Math.floor(rng() * 4) + 2 : Math.floor(rng() * 6) + 5;
  const careerStart = 2026 - (yearsWithTeam + Math.floor(rng() * 18) + 4);
  const bornYear = careerStart - (Math.floor(rng() * 12) + 28);
  return {
    name,
    position: 'Head Coach',
    team: fmtTeamLabel(team as any),
    reputation: 55 + Math.floor(rng() * 25),
    nationality,
    bornYear,
    yearsWithTeam,
    careerStartYear: careerStart,
    isPlaceholder: true,
  };
}

export function makePlaceholderGM(
  team: NBATeam | { id?: number; tid?: number; name: string; region?: string; logoUrl?: string },
  opts?: { country?: string; nameData?: NameData },
): PlaceholderGM {
  const seed = seedFromTeam(team as any) ^ 0xa5a5a5;
  const rng = rngFromSeed(seed);
  const nameData = opts?.nameData ?? getNameData();
  const homeCountry = opts?.country ?? '';
  const nationality = pickCountry(homeCountry, rng);
  const name = pickNameFromCountry(nationality, nameData, rng);
  const jitter = (base: number) =>
    Math.max(40, Math.min(95, base + Math.floor(rng() * 21) - 10));
  return {
    name,
    position: 'General Manager',
    team: fmtTeamLabel(team as any),
    attributes: {
      trade_aggression: jitter(DEFAULT_GM_ATTRIBUTES.trade_aggression),
      scouting_focus:   jitter(DEFAULT_GM_ATTRIBUTES.scouting_focus),
      work_ethic:       jitter(DEFAULT_GM_ATTRIBUTES.work_ethic),
      spending:         jitter(DEFAULT_GM_ATTRIBUTES.spending),
    },
    playerPortraitUrl: (team as any).logoUrl
      || `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=1a1a2e&color=FDB927&size=512&bold=true`,
    nationality,
    isPlaceholder: true,
  };
}

/**
 * Build StaffData additions for every non-NBA team in state. Result is
 * meant to be merged into the existing `state.staff` payload after the
 * NBA staff gist loads — same shape, just appended arrays.
 */
export function generatePlaceholderNonNBAStaff(
  state: Pick<GameState, 'nonNBATeams'>,
): { coaches: StaffMember[]; gms: StaffMember[]; owners: StaffMember[] } {
  const nameData = getNameData();
  const coaches: StaffMember[] = [];
  const gms: StaffMember[] = [];
  const owners: StaffMember[] = [];
  for (const t of state.nonNBATeams ?? []) {
    const stub: any = { id: t.tid, tid: t.tid, name: t.name, region: t.region, logoUrl: t.logoUrl };
    const country = getTeamCountry(stub as NBATeam, state as any);
    const coach = makePlaceholderCoach(stub, { country, nameData });
    const gm = makePlaceholderGM(stub, { country, nameData });
    coaches.push({
      name: coach.name,
      team: t.name,
      position: 'Head Coach',
      jobTitle: 'Head Coach',
      teamLogoUrl: t.logoUrl,
    } as StaffMember);
    gms.push({
      name: gm.name,
      team: t.name,
      position: 'GM',
      jobTitle: 'General Manager',
      teamLogoUrl: t.logoUrl,
    } as StaffMember);
    // Owner = same country bias, separate roll.
    const ownerRng = rngFromSeed(seedFromTeam(stub) ^ 0x5a5a5a);
    const ownerCountry = pickCountry(country, ownerRng);
    const ownerName = pickNameFromCountry(ownerCountry, nameData, ownerRng);
    owners.push({
      name: ownerName,
      team: t.name,
      position: 'Owner',
      jobTitle: 'Majority Owner',
      teamLogoUrl: t.logoUrl,
    } as StaffMember);
  }
  return { coaches, gms, owners };
}

