/**
 * Award system types — data-driven, league-agnostic.
 *
 * Every award is a record in AwardRegistry. The same calculator can power
 * multiple awards (e.g. NBA MVP + EL MVP + ACB MVP all use mvpCalc, with
 * different player pools). Branding is per-mode via `brandedAs`.
 */
import type { NBAPlayer, NBATeam, NBAGMStat, StaffData, GameState } from '../../types';

export type AwardScope = 'player' | 'coach';

export type AwardCategory =
  | 'season'       // MVP, DPOY
  | 'defense'      // All-Defensive Teams
  | 'rookie'       // ROY, All-Rookie
  | 'rising'       // Rising Star (under-23), Best Young Player (under-22)
  | 'stat-leader'  // Top Scorer, Rebound Leader, PIR, etc.
  | 'coach'        // COY, Best Coach
  | 'all-team'     // All-League 1st/2nd/3rd
  | 'postseason';  // Finals MVP, Final Four MVP (assigned externally)

export type CalculatorId =
  | 'mvp' | 'dpoy' | 'rookie' | 'young' | 'stat-leader'
  | 'pir' | 'coy' | 'all-team' | 'six-man' | 'mip'
  | 'postseason'; // marker — actually written by playoff resolver

export type PoolId = 'nba' | 'endesa' | 'euroleague' | 'all-active';

export type EligibilityKey =
  | 'min-games' | 'rookie-year' | 'under-22' | 'under-23'
  | 'bench-role' | 'pos-G' | 'pos-F' | 'pos-C';

export type UIMode = 'nba' | 'euro_isolated' | 'fictional';

export interface TrophyDef {
  /** Lucide icon name (e.g. 'star', 'trophy', 'flame'). */
  icon: string;
  /** Tailwind color hue: 'yellow' | 'blue' | 'emerald' | etc. */
  color: string;
  /** Short blurb shown on trophy detail. */
  blurb?: string;
}

/**
 * A calculator takes a snapshot of the league and returns scored candidates.
 * Pure — no state mutation. Used both for "races" (live projections) and
 * "announce" (winner selection from final stats).
 */
export interface CalculatorContext {
  players: NBAPlayer[];
  teams: NBATeam[];
  nonNBATeams: any[];
  season: number;
  staff?: StaffData | null;
  poolTids: Set<number>;
  minGames: number;
  /** Optional arg payload (e.g. { metric: 'pts' } for stat-leader). */
  args?: any;
}

export interface AwardCandidate {
  player?: NBAPlayer;
  coachName?: string;
  team: NBATeam;
  score: number;
  odds: string;
  stats?: NBAGMStat;
  // For all-team selections
  teamIndex?: number; // 0 = 1st, 1 = 2nd, 2 = 3rd
  pos?: string;
}

export type Calculator = (ctx: CalculatorContext) => AwardCandidate[];

export interface AwardDefinition {
  /** Stable id — used as state.historicalAwards.type's slug + settings key. */
  id: string;
  category: AwardCategory;
  scope: AwardScope;

  // Display
  name: string;
  shortName: string;
  description: string;
  trophy: TrophyDef;

  // Calculation
  calculatorId: CalculatorId;
  /** Args passed to the calculator (e.g. { metric: 'pts' }). */
  calculatorArgs?: any;
  eligibility: EligibilityKey[];
  poolId: PoolId;

  // Defaults (overridable via leagueStats.awardSettings)
  defaultActiveIn: UIMode[];
  defaultAnnounceMD: { month: number; day: number };
  minGamesDefault: number;
  fatigueFactor?: number;

  /**
   * Per-mode branding override. When the active uiMode key exists here, the
   * award is displayed with the branded name + trophy instead of the
   * generic `name` field. Same calculator runs underneath.
   */
  brandedAs?: Partial<Record<UIMode, { name: string; shortName?: string; trophy?: TrophyDef }>>;

  /**
   * Identifier persisted into `state.historicalAwards.type` for this award.
   * Defaults to the human `name`, but can be overridden when migrating from
   * legacy types (e.g. legacy 'MVP' stored as 'Most Valuable Player' in
   * player.awards). Keep stable across saves.
   */
  storedType?: string;
}

export interface AwardSettings {
  /** Per-award enable flag — overrides defaultActiveIn. */
  enabled: Record<string, boolean>;
  /** Per-award custom display name. */
  customNames?: Record<string, string>;
  /** Per-award announce date override. */
  announceDates?: Record<string, { month: number; day: number }>;
  /** Per-award min-games override. */
  minGames?: Record<string, number>;
}

/**
 * Resolved award for runtime — name/announceDate/minGames already merged
 * with commissioner overrides. AwardEngine works off these, not raw
 * AwardDefinitions.
 */
export interface ResolvedAward extends AwardDefinition {
  effectiveName: string;
  effectiveShortName: string;
  effectiveTrophy: TrophyDef;
  effectiveAnnounceDate: { month: number; day: number };
  effectiveMinGames: number;
  enabled: boolean;
}

export type GameStateView = Pick<
  GameState,
  'players' | 'teams' | 'nonNBATeams' | 'staff' | 'leagueStats' | 'historicalAwards'
>;

/**
 * Eligibility predicates — reusable across awards.
 * Each returns true if the player CAN be considered for the award.
 */
import type { NBAPlayer, NBAGMStat, NBATeam } from '../../types';
import type { EligibilityKey } from './types';

function playerAge(p: NBAPlayer, season: number): number {
  const born = (p as any).born?.year;
  if (born && season) return season - born;
  return (p as any).age ?? 25;
}

function isProportionallyEligible(
  stat: NBAGMStat,
  team: NBATeam,
  minPerSeason: number,
  fullSeasonRef: number,
): boolean {
  const teamGames = (team.wins ?? 0) + (team.losses ?? 0);
  if (teamGames === 0) return stat.gp >= 1;
  if (teamGames >= fullSeasonRef) return stat.gp >= minPerSeason;
  const threshold = teamGames * (minPerSeason / fullSeasonRef);
  return stat.gp >= threshold;
}

export function checkEligibility(
  keys: EligibilityKey[],
  player: NBAPlayer,
  stat: NBAGMStat | undefined,
  team: NBATeam | undefined,
  season: number,
  minGames: number,
  fullSeasonRef = 82,
): boolean {
  if (!stat || !team) return false;
  for (const k of keys) {
    switch (k) {
      case 'min-games':
        if (!isProportionallyEligible(stat, team, minGames, fullSeasonRef)) return false;
        break;
      case 'rookie-year':
        if (player.draft?.year !== season - 1) return false;
        break;
      case 'under-22':
        if (playerAge(player, season) >= 22) return false;
        break;
      case 'under-23':
        if (playerAge(player, season) >= 23) return false;
        break;
      case 'bench-role':
        if ((stat.gs ?? 0) > (stat.gp ?? 0) / 2) return false;
        break;
      case 'pos-G': {
        const pos = (player.ratings?.[player.ratings.length - 1] as any)?.pos ?? player.pos ?? '';
        if (!/^(PG|SG|G)/i.test(pos)) return false;
        break;
      }
      case 'pos-F': {
        const pos = (player.ratings?.[player.ratings.length - 1] as any)?.pos ?? player.pos ?? '';
        if (!/^(SF|PF|F)/i.test(pos)) return false;
        break;
      }
      case 'pos-C': {
        const pos = (player.ratings?.[player.ratings.length - 1] as any)?.pos ?? player.pos ?? '';
        if (!/^C/i.test(pos)) return false;
        break;
      }
    }
  }
  return true;
}

export { playerAge };

/**
 * Pool resolution — given a poolId, return the set of valid tids.
 * 'all-active' = NBA team ids + every league the save participates in.
 */
import type { NBATeam } from '../../types';
import type { PoolId } from './types';

interface PoolContext {
  teams: NBATeam[];
  nonNBATeams: { tid: number; league?: string }[];
}

export function resolvePool(poolId: PoolId, ctx: PoolContext): Set<number> {
  const ids = new Set<number>();
  switch (poolId) {
    case 'nba':
      for (const t of ctx.teams) if (t.id >= 0 && t.id < 100) ids.add(t.id);
      break;
    case 'endesa':
      for (const t of ctx.nonNBATeams ?? []) if (t.tid >= 5000 && t.tid < 6000) ids.add(t.tid);
      for (const t of ctx.teams)            if (t.id  >= 5000 && t.id  < 6000) ids.add(t.id);
      break;
    case 'euroleague':
      for (const t of ctx.nonNBATeams ?? []) if (t.tid >= 1000 && t.tid < 2000) ids.add(t.tid);
      // Merged Endesa-tid clubs that ALSO play EL (Real Madrid, Barça)
      for (const t of ctx.teams) if (t.id >= 5000 && t.id < 6000) ids.add(t.id);
      break;
    case 'all-active':
      for (const t of ctx.teams) ids.add(t.id);
      for (const t of ctx.nonNBATeams ?? []) ids.add(t.tid);
      break;
  }
  return ids;
}

/** Standard reference for "full regular season" — depends on the pool. */
export function fullSeasonRefFor(poolId: PoolId): number {
  switch (poolId) {
    case 'nba': return 82;
    case 'endesa': return 34;
    case 'euroleague': return 38;
    case 'all-active': return 82;
  }
}

/**
 * All award score calculators in one file — pure, no state mutation.
 *
 * Each calculator receives a CalculatorContext (players + teams + pool +
 * season + args) and returns sorted candidates. The "winner" is index 0.
 *
 * Same calculator powers multiple AwardDefinition records:
 *   - mvpCalc → NBA MVP, EL MVP, ACB MVP, Fictional MVP
 *   - statLeaderCalc → Top Scorer / Reb / Ast / Stl / Blk / 3P
 */
import type { NBAPlayer, NBAGMStat, NBATeam } from '../../types';
import type { Calculator, CalculatorContext, AwardCandidate, CalculatorId } from './types';
import { checkEligibility, playerAge } from './eligibility';

const getTrb = (s: any) => s.trb || s.reb || (s.orb || 0) + (s.drb || 0);

const bestStat = (stats: NBAGMStat[] | undefined, season: number): NBAGMStat | undefined => {
  if (!stats) return undefined;
  for (const s of [season, season - 1]) {
    const filtered = stats.filter(st => st.season === s && !st.playoffs);
    if (filtered.length > 0) return filtered.reduce((p, c) => (p.gp >= c.gp ? p : c));
  }
  return undefined;
};

/** FIBA PIR. We approximate FoulsDrawn ≈ FTA × 0.4 since we don't track it. */
function computePIR(s: NBAGMStat): number {
  const gp = s.gp || 1;
  const fgMissed = ((s.fga ?? 0) - (s.fg ?? 0));
  const ftMissed = ((s.fta ?? 0) - (s.ft ?? 0));
  const foulsDrawn = (s.fta ?? 0) * 0.4;
  const pir = (s.pts + getTrb(s) + s.ast + s.stl + s.blk + foulsDrawn)
            - (fgMissed + ftMissed + (s.tov ?? 0) + (s.pf ?? 0));
  return pir / gp;
}

const PLAYER_AWARD_COUNT = (p: NBAPlayer, types: string[]): number =>
  p.awards?.filter(a => types.includes(a.type)).length ?? 0;

function assignOdds(arr: AwardCandidate[]): AwardCandidate[] {
  const top = arr[0]?.score || 1;
  return arr.map((c, i) => {
    const ratio = c.score / top;
    let odds: string;
    if (i === 0) odds = `${Math.round(45 + ratio * 25)}%`;
    else if (i === 1) odds = `${Math.round(18 + ratio * 8)}%`;
    else if (i === 2) odds = `${Math.round(10 + ratio * 5)}%`;
    else odds = `+${Math.round(800 + (1 - ratio) * 1500)}`;
    return { ...c, odds };
  });
}

function inPool(p: NBAPlayer, pool: Set<number>): boolean {
  return pool.has(p.tid);
}

function getTeam(teams: NBATeam[], tid: number): NBATeam | undefined {
  return teams.find(t => t.id === tid);
}

function stubTeam(tid: number): NBATeam {
  return { id: tid, name: 'Unknown', abbrev: '?', wins: 0, losses: 0 } as unknown as NBATeam;
}

// ─── MVP ────────────────────────────────────────────────────────────────────
export const mvpCalc: Calculator = (ctx) => {
  const candidates: AwardCandidate[] = [];
  for (const p of ctx.players) {
    if (!inPool(p, ctx.poolTids)) continue;
    const stat = bestStat(p.stats, ctx.season);
    const team = getTeam(ctx.teams, p.tid) ?? stubTeam(p.tid);
    const hasInjury = !!((p as any).injury && (p as any).injury.gamesRemaining > 0);
    if (!stat) continue;
    if (!checkEligibility(['min-games'], p, stat, team, ctx.season, ctx.minGames)) {
      // Injury exception: -3 games tolerance
      if (!hasInjury) continue;
      if (!checkEligibility(['min-games'], p, stat, team, ctx.season, Math.max(ctx.minGames - 3, 1))) continue;
    }
    const gp = stat.gp;
    const ppg = stat.pts / gp;
    const rpg = getTrb(stat) / gp;
    const apg = stat.ast / gp;
    if (ppg < 10) continue;
    const winPct = (team.wins ?? 0) / ((team.wins ?? 0) + (team.losses ?? 0) || 1);
    let score = (ppg * 1.2 + rpg * 0.5 + apg * 0.6) * (0.7 + winPct * 0.8);
    const pastMVPs = PLAYER_AWARD_COUNT(p, ['Most Valuable Player', 'Euroleague MVP', 'Liga ACB MVP']);
    score *= Math.max(0.925, 1 - pastMVPs * 0.025);
    candidates.push({ player: p, team, score, odds: '', stats: stat });
  }
  return assignOdds(candidates.sort((a, b) => b.score - a.score).slice(0, 10));
};

// ─── DPOY ───────────────────────────────────────────────────────────────────
export const dpoyCalc: Calculator = (ctx) => {
  const candidates: AwardCandidate[] = [];
  for (const p of ctx.players) {
    if (!inPool(p, ctx.poolTids)) continue;
    const stat = bestStat(p.stats, ctx.season);
    const team = getTeam(ctx.teams, p.tid) ?? stubTeam(p.tid);
    if (!stat || !checkEligibility(['min-games'], p, stat, team, ctx.season, ctx.minGames)) continue;
    const gp = stat.gp;
    const rpg = getTrb(stat) / gp;
    const spg = stat.stl / gp;
    const bpg = stat.blk / gp;
    const diq = (p.ratings?.[p.ratings.length - 1] as any)?.diq ?? 50;
    const defMult = Math.max(0.4, diq / 70);
    const winPct = (team.wins ?? 0) / ((team.wins ?? 0) + (team.losses ?? 0) || 1);
    let score = (spg * 3.5 + bpg * 3.0 + rpg * 0.15) * (0.6 + winPct * 0.8) * defMult;
    const past = PLAYER_AWARD_COUNT(p, ['Defensive Player of the Year', 'Euroleague Best Defender']);
    score *= Math.max(0.925, 1 - past * 0.025);
    candidates.push({ player: p, team, score, odds: '', stats: stat });
  }
  return assignOdds(candidates.sort((a, b) => b.score - a.score).slice(0, 10));
};

// ─── Rookie of the Year ─────────────────────────────────────────────────────
export const rookieCalc: Calculator = (ctx) => {
  const candidates: AwardCandidate[] = [];
  for (const p of ctx.players) {
    if (!inPool(p, ctx.poolTids)) continue;
    if (p.draft?.year !== ctx.season - 1) continue;
    const stat = bestStat(p.stats, ctx.season);
    const team = getTeam(ctx.teams, p.tid) ?? stubTeam(p.tid);
    if (!stat || !checkEligibility(['min-games'], p, stat, team, ctx.season, ctx.minGames)) continue;
    const gp = stat.gp;
    const score = (stat.pts / gp) * 1.0 + (getTrb(stat) / gp) * 0.5 + (stat.ast / gp) * 0.5;
    candidates.push({ player: p, team, score, odds: '', stats: stat });
  }
  return assignOdds(candidates.sort((a, b) => b.score - a.score).slice(0, 10));
};

// ─── Sixth Man of the Year ──────────────────────────────────────────────────
export const sixManCalc: Calculator = (ctx) => {
  const candidates: AwardCandidate[] = [];
  for (const p of ctx.players) {
    if (!inPool(p, ctx.poolTids)) continue;
    const stat = bestStat(p.stats, ctx.season);
    const team = getTeam(ctx.teams, p.tid) ?? stubTeam(p.tid);
    if (!stat || !checkEligibility(['min-games', 'bench-role'], p, stat, team, ctx.season, ctx.minGames)) continue;
    const gp = stat.gp;
    const tsPct = (stat as any).tsPct || 52;
    const efficiencyBonus = (tsPct - 52) * 0.05;
    let score = (stat.pts / gp) * 1.2 + (getTrb(stat) / gp) * 0.4 + (stat.ast / gp) * 0.4 + efficiencyBonus;
    score *= Math.max(0.925, 1 - PLAYER_AWARD_COUNT(p, ['Sixth Man of the Year']) * 0.025);
    candidates.push({ player: p, team, score, odds: '', stats: stat });
  }
  return assignOdds(candidates.sort((a, b) => b.score - a.score).slice(0, 10));
};

// ─── Most Improved Player ───────────────────────────────────────────────────
export const mipCalc: Calculator = (ctx) => {
  const candidates: AwardCandidate[] = [];
  for (const p of ctx.players) {
    if (!inPool(p, ctx.poolTids)) continue;
    const cur = bestStat(p.stats, ctx.season);
    const prev = bestStat(p.stats, ctx.season - 1);
    const team = getTeam(ctx.teams, p.tid) ?? stubTeam(p.tid);
    if (!cur || !prev || !checkEligibility(['min-games'], p, cur, team, ctx.season, ctx.minGames)) continue;
    if ((prev.gp ?? 0) < 20) continue;
    const curPPG = cur.pts / cur.gp;
    const prevPPG = prev.pts / prev.gp;
    const ppgJump = curPPG - prevPPG;
    if (ppgJump < 2) continue;
    let score = ppgJump * 4 + (curPPG - 14) * 0.3;
    candidates.push({ player: p, team, score, odds: '', stats: cur });
  }
  return assignOdds(candidates.sort((a, b) => b.score - a.score).slice(0, 10));
};

// ─── Young / Rising Star (under-22 or under-23, depending on args) ──────────
export const youngCalc: Calculator = (ctx) => {
  const cap = ctx.args?.ageCap ?? 23;
  const candidates: AwardCandidate[] = [];
  for (const p of ctx.players) {
    if (!inPool(p, ctx.poolTids)) continue;
    if (playerAge(p, ctx.season) >= cap) continue;
    const stat = bestStat(p.stats, ctx.season);
    const team = getTeam(ctx.teams, p.tid) ?? stubTeam(p.tid);
    if (!stat || stat.gp < Math.max(8, ctx.minGames / 2)) continue;
    const gp = stat.gp;
    const score = (stat.pts / gp) * 1.0 + (getTrb(stat) / gp) * 0.4 + (stat.ast / gp) * 0.4 + computePIR(stat) * 0.3;
    candidates.push({ player: p, team, score, odds: '', stats: stat });
  }
  return assignOdds(candidates.sort((a, b) => b.score - a.score).slice(0, 10));
};

// ─── Stat Leader (metric-driven: 'pts' | 'reb' | 'ast' | 'stl' | 'blk' | '3p') ──
export const statLeaderCalc: Calculator = (ctx) => {
  const metric: string = ctx.args?.metric ?? 'pts';
  const metricFn = (s: NBAGMStat): number => {
    const gp = s.gp || 1;
    switch (metric) {
      case 'pts': return s.pts / gp;
      case 'reb': return getTrb(s) / gp;
      case 'ast': return s.ast / gp;
      case 'stl': return s.stl / gp;
      case 'blk': return s.blk / gp;
      case '3p':  return ((s as any).tp ?? (s as any).fg3 ?? 0) / gp;
      default:    return s.pts / gp;
    }
  };
  const candidates: AwardCandidate[] = [];
  for (const p of ctx.players) {
    if (!inPool(p, ctx.poolTids)) continue;
    const stat = bestStat(p.stats, ctx.season);
    const team = getTeam(ctx.teams, p.tid) ?? stubTeam(p.tid);
    if (!stat || stat.gp < Math.max(8, ctx.minGames / 2)) continue;
    candidates.push({ player: p, team, score: metricFn(stat), odds: '', stats: stat });
  }
  return assignOdds(candidates.sort((a, b) => b.score - a.score).slice(0, 10));
};

// ─── PIR Leader ─────────────────────────────────────────────────────────────
export const pirCalc: Calculator = (ctx) => {
  const candidates: AwardCandidate[] = [];
  for (const p of ctx.players) {
    if (!inPool(p, ctx.poolTids)) continue;
    const stat = bestStat(p.stats, ctx.season);
    const team = getTeam(ctx.teams, p.tid) ?? stubTeam(p.tid);
    if (!stat || stat.gp < Math.max(8, ctx.minGames / 2)) continue;
    candidates.push({ player: p, team, score: computePIR(stat), odds: '', stats: stat });
  }
  return assignOdds(candidates.sort((a, b) => b.score - a.score).slice(0, 10));
};

// ─── Coach of the Year ──────────────────────────────────────────────────────
export const coyCalc: Calculator = (ctx) => {
  const candidates: AwardCandidate[] = [];
  for (const t of ctx.teams) {
    if (!ctx.poolTids.has(t.id)) continue;
    const wins = t.wins ?? 0;
    const losses = t.losses ?? 0;
    const winPct = wins / (wins + losses || 1);
    const prevWins = (t.seasons ?? [])[(t.seasons ?? []).length - 2]?.won ?? wins;
    const improvement = wins - prevWins;
    const coach = ctx.staff?.coaches?.find(c => (c.team ?? '').toLowerCase().trim() === t.name.toLowerCase().trim());
    const coachName = coach?.name ?? `${t.name} Head Coach`;
    const score = winPct * 70 + improvement * 1.5;
    candidates.push({ coachName, team: t, score, odds: '', wins, losses, improvement } as any);
  }
  return assignOdds(candidates.filter(c => c.score > 0).sort((a, b) => b.score - a.score).slice(0, 10));
};

// ─── All-Team selections ────────────────────────────────────────────────────
/** Returns up to 15 candidates (3 teams of 5). Args: { numTeams: 3, perTeam: 5 } */
export const allTeamCalc: Calculator = (ctx) => {
  const numTeams = ctx.args?.numTeams ?? 3;
  const perTeam = ctx.args?.perTeam ?? 5;
  const candidates: AwardCandidate[] = [];
  for (const p of ctx.players) {
    if (!inPool(p, ctx.poolTids)) continue;
    const stat = bestStat(p.stats, ctx.season);
    const team = getTeam(ctx.teams, p.tid) ?? stubTeam(p.tid);
    if (!stat || !checkEligibility(['min-games'], p, stat, team, ctx.season, ctx.minGames)) continue;
    const gp = stat.gp;
    const score = (stat.pts / gp) * 1.0 + (getTrb(stat) / gp) * 0.5 + (stat.ast / gp) * 0.6 + computePIR(stat) * 0.4;
    const pos = (p.ratings?.[p.ratings.length - 1] as any)?.pos ?? p.pos ?? 'F';
    candidates.push({ player: p, team, score, odds: '', stats: stat, pos });
  }
  const sorted = candidates.sort((a, b) => b.score - a.score).slice(0, numTeams * perTeam);
  return sorted.map((c, idx) => ({ ...c, teamIndex: Math.floor(idx / perTeam) }));
};

// ─── Postseason marker (not actually computed — playoff resolver writes it) ─
export const postseasonCalc: Calculator = () => [];

// ─── Registry of calculators ────────────────────────────────────────────────
export const CALCULATORS: Record<CalculatorId, Calculator> = {
  'mvp': mvpCalc,
  'dpoy': dpoyCalc,
  'rookie': rookieCalc,
  'six-man': sixManCalc,
  'mip': mipCalc,
  'young': youngCalc,
  'stat-leader': statLeaderCalc,
  'pir': pirCalc,
  'coy': coyCalc,
  'all-team': allTeamCalc,
  'postseason': postseasonCalc,
};

/**
 * AwardEngine — runtime layer over AwardRegistry.
 *
 * Two public entry points:
 *   - resolveAwardsForState(state)  → list of enabled, brand-mapped awards
 *   - computeRaces(state, awardId)  → top-N candidates for a race
 *   - announce(state, awardId)      → Partial<GameState> writing the winner
 */
import type {
  AwardDefinition, ResolvedAward, AwardSettings, AwardCandidate,
  CalculatorContext, GameStateView, UIMode, TrophyDef,
} from './types';
import { AWARD_REGISTRY, getAwardDefinition } from './AwardRegistry';
import { CALCULATORS } from './calculators';
import { resolvePool, fullSeasonRefFor } from './pool';
import type { HistoricalAward, GameState } from '../../types';

// ─── Settings defaults ──────────────────────────────────────────────────────

function getUIMode(state: GameStateView): UIMode {
  const m = (state.leagueStats as any)?.uiMode ?? 'nba';
  return (m === 'euro_isolated' || m === 'fictional') ? m : 'nba';
}

/** Build default AwardSettings for a save based on its uiMode. */
export function defaultAwardSettings(uiMode: UIMode): AwardSettings {
  const enabled: Record<string, boolean> = {};
  for (const a of AWARD_REGISTRY) {
    enabled[a.id] = a.defaultActiveIn.includes(uiMode);
  }
  return { enabled };
}

/** Read live settings, filling holes from defaults. */
function effectiveSettings(state: GameStateView): AwardSettings {
  const uiMode = getUIMode(state);
  const stored: AwardSettings | undefined = (state.leagueStats as any)?.awardSettings;
  if (!stored) return defaultAwardSettings(uiMode);
  // Fill any new award ids with mode defaults
  const enabled: Record<string, boolean> = { ...stored.enabled };
  for (const a of AWARD_REGISTRY) {
    if (!(a.id in enabled)) enabled[a.id] = a.defaultActiveIn.includes(uiMode);
  }
  return { ...stored, enabled };
}

// ─── Award resolution (merge settings overrides) ────────────────────────────

export function resolveAward(def: AwardDefinition, settings: AwardSettings, uiMode: UIMode): ResolvedAward {
  const brand = def.brandedAs?.[uiMode];
  const effectiveName = settings.customNames?.[def.id] ?? brand?.name ?? def.name;
  const effectiveShortName = brand?.shortName ?? def.shortName;
  const effectiveTrophy: TrophyDef = brand?.trophy ?? def.trophy;
  const effectiveAnnounceDate = settings.announceDates?.[def.id] ?? def.defaultAnnounceMD;
  const effectiveMinGames = settings.minGames?.[def.id] ?? def.minGamesDefault;
  return {
    ...def,
    effectiveName,
    effectiveShortName,
    effectiveTrophy,
    effectiveAnnounceDate,
    effectiveMinGames,
    enabled: settings.enabled[def.id] ?? def.defaultActiveIn.includes(uiMode),
  };
}

export function resolveAwardsForState(state: GameStateView): ResolvedAward[] {
  const uiMode = getUIMode(state);
  const settings = effectiveSettings(state);
  return AWARD_REGISTRY.map(d => resolveAward(d, settings, uiMode));
}

export function getEnabledAwards(state: GameStateView): ResolvedAward[] {
  return resolveAwardsForState(state).filter(a => a.enabled);
}

// ─── Compute (race projection) ──────────────────────────────────────────────

export function computeRaces(state: GameStateView, awardId: string): AwardCandidate[] {
  const def = getAwardDefinition(awardId);
  if (!def) return [];
  const uiMode = getUIMode(state);
  const settings = effectiveSettings(state);
  const resolved = resolveAward(def, settings, uiMode);
  if (def.calculatorId === 'postseason') return []; // not race-computable

  const calc = CALCULATORS[def.calculatorId];
  if (!calc) return [];

  const poolTids = resolvePool(def.poolId, {
    teams: state.teams,
    nonNBATeams: (state.nonNBATeams ?? []) as any,
  });

  const ctx: CalculatorContext = {
    players: state.players,
    teams: state.teams,
    nonNBATeams: state.nonNBATeams ?? [],
    season: (state.leagueStats as any)?.year ?? new Date().getFullYear(),
    staff: state.staff,
    poolTids,
    minGames: resolved.effectiveMinGames,
    args: def.calculatorArgs,
  };
  return calc(ctx);
}

/** All races for an enabled set — useful for the AwardRacesView grid. */
export function computeAllRaces(state: GameStateView): Record<string, AwardCandidate[]> {
  const out: Record<string, AwardCandidate[]> = {};
  for (const a of getEnabledAwards(state)) {
    out[a.id] = computeRaces(state, a.id);
  }
  return out;
}

// ─── Announce (commit winner to historicalAwards + player.awards) ───────────

const PLAYER_AWARD_TYPE_MAP: Record<string, string> = {
  MVP: 'Most Valuable Player',
  DPOY: 'Defensive Player of the Year',
  ROY: 'Rookie of the Year',
  SMOY: 'Sixth Man of the Year',
  MIP: 'Most Improved Player',
};

export function announce(state: GameState, awardId: string): Partial<GameState> {
  const def = getAwardDefinition(awardId);
  if (!def) return {};
  const uiMode = getUIMode(state as unknown as GameStateView);
  const settings = effectiveSettings(state as unknown as GameStateView);
  const resolved = resolveAward(def, settings, uiMode);
  if (!resolved.enabled) return {};

  const season = state.leagueStats.year;
  const storedType = def.storedType ?? resolved.effectiveName;

  // Idempotency — already awarded this season?
  if ((state.historicalAwards ?? []).some(a => a.season === season && a.type === storedType)) return {};

  // All-Team awards: write multiple rows
  if (def.category === 'all-team') {
    return announceAllTeam(state, def, resolved, storedType);
  }
  if (def.calculatorId === 'postseason') {
    // Postseason awards are written by the playoff resolver, not here.
    return {};
  }

  const candidates = computeRaces(state as unknown as GameStateView, awardId);
  const winner = candidates[0];
  if (!winner) return {};

  const newAwards: HistoricalAward[] = [];
  let updatedPlayers = state.players;

  if (def.scope === 'coach' && winner.coachName) {
    newAwards.push({
      season,
      type: storedType,
      name: winner.coachName,
      tid: winner.team?.id,
    });
  } else if (winner.player) {
    newAwards.push({
      season,
      type: storedType,
      name: winner.player.name,
      pid: winner.player.internalId,
      tid: winner.team?.id,
    });
    const playerAwardType = PLAYER_AWARD_TYPE_MAP[storedType] ?? resolved.effectiveName;
    updatedPlayers = updatedPlayers.map(p =>
      p.internalId === winner.player!.internalId
        ? { ...p, awards: [...(p.awards ?? []), { season, type: playerAwardType }] }
        : p
    );
  }

  return {
    players: updatedPlayers,
    historicalAwards: [...(state.historicalAwards ?? []), ...newAwards],
  };
}

function announceAllTeam(
  state: GameState,
  def: AwardDefinition,
  resolved: ResolvedAward,
  _storedType: string,
): Partial<GameState> {
  const season = state.leagueStats.year;
  const candidates = computeRaces(state as unknown as GameStateView, def.id);
  if (candidates.length === 0) return {};

  // Bucket by teamIndex (0 = 1st team, 1 = 2nd team, 2 = 3rd team)
  const teamNames: Record<string, string[]> = {
    'all-league':     ['All-NBA First Team', 'All-NBA Second Team', 'All-NBA Third Team'],
    'all-defensive':  ['All-Defensive First Team', 'All-Defensive Second Team'],
    'all-rookie':     ['All-Rookie First Team', 'All-Rookie Second Team'],
    'all-euroleague': ['All-EuroLeague First Team', 'All-EuroLeague Second Team'],
  };
  const labels = teamNames[def.id] ?? [resolved.effectiveName];

  // For Euro mode, rebrand the "All-NBA"-prefixed labels via brand mapping
  const uiMode = getUIMode(state as unknown as GameStateView);
  const finalLabels = uiMode === 'euro_isolated' && def.id === 'all-league'
    ? labels.map(l => l.replace('All-NBA', 'All-League'))
    : labels;

  const newAwards: HistoricalAward[] = [];
  let updatedPlayers = state.players;
  for (const c of candidates) {
    if (!c.player || c.teamIndex === undefined) continue;
    const label = finalLabels[c.teamIndex] ?? finalLabels[finalLabels.length - 1];
    newAwards.push({
      season,
      type: label,
      name: c.player.name,
      pid: c.player.internalId,
      tid: c.team?.id,
    });
    updatedPlayers = updatedPlayers.map(p =>
      p.internalId === c.player!.internalId
        ? { ...p, awards: [...(p.awards ?? []), { season, type: label }] }
        : p
    );
  }
  return {
    players: updatedPlayers,
    historicalAwards: [...(state.historicalAwards ?? []), ...newAwards],
  };
}

// ─── Schedule lookup — for lazySimRunner ────────────────────────────────────

/** Get all announce events for a season — enabled awards only, no postseason. */
export function getAnnouncementEvents(
  state: GameStateView,
  seasonYear: number,
): Array<{ date: string; awardId: string; phase: string }> {
  return getEnabledAwards(state)
    .filter(a => a.calculatorId !== 'postseason')
    .map(a => {
      const mm = String(a.effectiveAnnounceDate.month).padStart(2, '0');
      const dd = String(a.effectiveAnnounceDate.day).padStart(2, '0');
      return {
        date: `${seasonYear}-${mm}-${dd}`,
        awardId: a.id,
        phase: `Announcing ${a.effectiveName}...`,
      };
    });
}

