/**
 * AwardRacesView — universal, data-driven from AwardRegistry.
 *
 * Reads enabled awards from `state.leagueStats.awardSettings` (managed in
 * Commissioner Rules → Honors → Award Catalog). Renders a tab per enabled
 * award; each tab uses AwardEngine.computeRaces to live-project winners.
 *
 * NBA mode and Euro Isolated mode share this view — the difference is just
 * which awards are enabled in their respective default settings. Same
 * applies to fictional saves and future templates.
 */
import React, { useState, useMemo, useEffect } from 'react';
import { useGame } from '../../store/GameContext';
import { motion, AnimatePresence } from 'motion/react';
import { Trophy, Info } from 'lucide-react';
import { PlayerBioView } from '../central/view/PlayerBioView';
import { NBAPlayer } from '../../types';
import { fetchCoachData, getCoachPhoto } from '../../data/photos/coaches';
import { RankedPersonCard, StatPills } from '../shared/ui';
import { getOwnTeamId } from '../../utils/helpers';
import { PlayerPortrait } from '../shared/PlayerPortrait';
import {
  resolveAwardsForState, computeRaces,
} from '../../services/awards/AwardEngine';
import type { ResolvedAward, AwardCandidate } from '../../services/awards/types';
import {
  Award, Star, Shield, Sparkles, Flame, Target, Circle, Share2,
  Zap, Users, UserCheck, Crown, Medal, TrendingUp,
} from 'lucide-react';

const ICON_MAP: Record<string, any> = {
  star: Star, trophy: Trophy, shield: Shield, sparkles: Sparkles,
  flame: Flame, circle: Circle, 'share-2': Share2, zap: Zap, target: Target,
  award: Award, users: Users, 'user-check': UserCheck, crown: Crown,
  medal: Medal, baby: Sparkles, 'trending-up': TrendingUp,
};

const COLOR_MAP: Record<string, string> = {
  yellow: 'text-yellow-400', blue: 'text-blue-400', emerald: 'text-emerald-400',
  orange: 'text-orange-400', purple: 'text-purple-400', teal: 'text-teal-400',
  amber: 'text-amber-400', sky: 'text-sky-400', pink: 'text-pink-400',
  indigo: 'text-indigo-400', silver: 'text-slate-300',
};

export const AwardRacesView: React.FC = () => {
  const { state } = useGame();
  const ownTid = getOwnTeamId(state);
  const [viewingPlayer, setViewingPlayer] = useState<NBAPlayer | null>(null);
  const [_coachPhotosLoaded, setCoachPhotosLoaded] = useState(false);

  useEffect(() => {
    fetchCoachData().then(() => setCoachPhotosLoaded(true));
  }, []);

  // All enabled awards in declared registry order (= sidebar order).
  const enabledAwards = useMemo<ResolvedAward[]>(
    () => resolveAwardsForState(state as any).filter(a => a.enabled),
    [state.leagueStats?.awardSettings, state.players, state.teams, state.staff],
  );

  const [selectedId, setSelectedId] = useState<string>(enabledAwards[0]?.id ?? '');
  useEffect(() => {
    if (!enabledAwards.some(a => a.id === selectedId)) {
      setSelectedId(enabledAwards[0]?.id ?? '');
    }
  }, [enabledAwards, selectedId]);

  const selected = enabledAwards.find(a => a.id === selectedId);

  // Compute races for the selected award (live projection).
  const races = useMemo<AwardCandidate[]>(() => {
    if (!selected) return [];
    if (selected.calculatorId === 'postseason') return [];
    return computeRaces(state as any, selected.id);
  }, [selected, state.players, state.teams, state.staff, state.leagueStats?.year]);

  const seasonAwards = (state.historicalAwards ?? []).filter(a => a.season === state.leagueStats?.year);
  const announced = !!selected && seasonAwards.some(a => a.type === (selected.storedType ?? selected.effectiveName));

  // Don't show projections before any games have been played.
  const totalGP = state.teams.reduce((sum, t) => sum + (t.wins ?? 0) + (t.losses ?? 0), 0);
  const seasonNotStarted = totalGP === 0;

  if (viewingPlayer) {
    return <PlayerBioView player={viewingPlayer} onBack={() => setViewingPlayer(null)} />;
  }

  if (enabledAwards.length === 0) {
    return (
      <div className="h-full flex flex-col bg-slate-950 items-center justify-center gap-4 p-12 text-center">
        <Trophy className="text-slate-700" size={48} />
        <h2 className="text-2xl font-black text-white uppercase tracking-tight">No Awards Enabled</h2>
        <p className="text-slate-500 text-sm max-w-md">
          Open Commissioner → Rules → Honors and enable at least one award in the Award Catalog.
        </p>
      </div>
    );
  }

  if (seasonNotStarted) {
    return (
      <div className="h-full flex flex-col bg-slate-950 items-center justify-center gap-4 p-12 text-center">
        <Trophy className="text-slate-700" size={48} />
        <h2 className="text-2xl font-black text-white uppercase tracking-tight">Award Races</h2>
        <p className="text-slate-500 text-sm max-w-md">
          Projections will appear once the {(state.leagueStats?.year ?? 0) - 1}–{String(state.leagueStats?.year ?? 0).slice(-2)} regular season begins.
        </p>
      </div>
    );
  }

  if (!selected) return null;

  const Icon = ICON_MAP[selected.effectiveTrophy.icon] ?? Trophy;
  const iconColorClass = COLOR_MAP[selected.effectiveTrophy.color] ?? 'text-yellow-400';

  // ─── Card renderers ──────────────────────────────────────────────────────

  const renderAllTeam = (candidates: AwardCandidate[]) => {
    // Bucket by teamIndex
    const buckets: AwardCandidate[][] = [[], [], []];
    for (const c of candidates) {
      const idx = c.teamIndex ?? 0;
      if (idx < buckets.length) buckets[idx].push(c);
    }
    const labels = ['1st Team', '2nd Team', '3rd Team'];
    return (
      <div>
        {buckets.filter(b => b.length > 0).map((bucket, ti) => (
          <div key={ti} className="mb-6">
