export const convertTo2KRating = (
  bbgmRating: number,
  hgtAttribute: number = 50,  // expects BBGM 0-100 attribute, NOT bio inches
  eliteSkillRating?: number   // highest single skill (tp, ins, spd, etc.) — adds +excess above 90
): number => {
  let rating = 0.88 * bbgmRating + 31;

  // Height bonus (existing): tall guys trend higher in 2K
  if (hgtAttribute > 68) {
    rating += (hgtAttribute - 68) * (6 / 32); // max +6 at hgt=100
  }

  // Three-point elite bonus: 90+ tp adds the excess.
  // Curry tp=95 → +5. Elite shooters open the offense → higher 2K overall.
  if (eliteSkillRating !== undefined && eliteSkillRating > 90) {
    rating += eliteSkillRating - 90;
  }

  rating = Math.round(rating);
  if (rating < 40) rating = 40;
  return Math.min(99, rating);
};

input.new_string:
export const convertTo2KRating = (
  bbgmRating: number,
  hgtAttribute: number = 50,  // expects BBGM 0-100 attribute, NOT bio inches
  eliteSkillRating?: number   // highest single skill (tp, ins, spd, etc.) — adds +excess above 90
): number => {
  // Guard against undefined/null/NaN inputs (e.g. Endesa BBGM rosters that ship without
  // `overallRating` set on every player). Without this guard a single bad input poisons
  // every downstream calc (team strength, leaders, etc.) with NaN.
  const safeBBGM = Number.isFinite(bbgmRating) ? bbgmRating : 50;
  const safeHgt  = Number.isFinite(hgtAttribute) ? hgtAttribute : 50;
  let rating = 0.88 * safeBBGM + 31;

  // Height bonus (existing): tall guys trend higher in 2K
  if (safeHgt > 68) {
    rating += (safeHgt - 68) * (6 / 32); // max +6 at hgt=100
  }

  // Three-point elite bonus: 90+ tp adds the excess.
  // Curry tp=95 → +5. Elite shooters open the offense → higher 2K overall.
  if (eliteSkillRating !== undefined && Number.isFinite(eliteSkillRating) && eliteSkillRating > 90) {
    rating += eliteSkillRating - 90;
  }

  rating = Math.round(rating);
  if (!Number.isFinite(rating) || rating < 40) rating = 40;
  return Math.min(99, rating);
};

