// Inline-PBP types. ZenGM-inspired: PBP-Events werden inline emittiert,
// die Running-Score wird AUS dem Event-Stream akkumuliert (nicht separat).
// Dadurch ist Drift zwischen Box-Score und PBP strukturell unmöglich.

import { PlayerPool, TeamId, Period } from '../live/playback/possessionTypes';

export type EventType =
  | 'jumpball'
  | 'made_fg'      // 2pt or 3pt or 4pt FG made
  | 'miss_fg'      // 2pt or 3pt or 4pt FG miss
  | 'ft'           // single free throw (made or missed)
  | 'reb'          // rebound (off or def)
  | 'tov'          // turnover (with optional steal)
  | 'foul'         // shooting/personal/intentional foul (start of FT trip if shooting)
  | 'sub'          // substitution
  | 'period_end'   // end of Q/OT
  | 'game_end';    // final buzzer

export interface InlineEvent {
  // Event identity & timing
  id: string;
  type: EventType;
  q: number;                // 1..numQuarters+otCount
  period: Period;           // "1st" | "2nd" | ... | "OT1" ...
  clock: string;            // "11:23" countdown
  gs: number;               // game-seconds elapsed since tip
  time: string;             // "1st 11:23" — convenience for UI

  // Team & lineups at moment of event
  tm: TeamId;               // which team owns the action
  possession: TeamId;       // who has the ball (for non-team events, == tm)
  lineupHOME: PlayerPool[];
  lineupAWAY: PlayerPool[];

  // Player & supplementary actors
  player?: PlayerPool;      // primary actor
  astPlayer?: PlayerPool;   // assist credit on made_fg
  rebounder?: PlayerPool;   // attached to miss_fg (legacy — usually a separate 'reb' event follows)
  blocker?: PlayerPool;     // attached to miss_fg when block
  stealer?: PlayerPool;     // attached to tov when stolen

  // Scoring contribution OF THIS EVENT (0 for miss/reb/tov/foul/sub/period_end)
  pts: number;

  // FG-kind flags
  is3?: boolean;            // 3-pt attempt
  is4?: boolean;            // 4-pt attempt (Euroleague/exhibition)
  isMake?: boolean;         // ft: was it made?
  isOffReb?: boolean;       // reb: offensive rebound

  // Foul/FT context
  inPenalty?: boolean;
  isFirstPenaltyFoul?: boolean;
  isFoulOut?: boolean;
  isIntentional?: boolean;

  // Sub context
  comingIn?: PlayerPool[];
  goingOut?: PlayerPool[];

  // Narrative (rendered once at emit-time, not on every render)
  desc: string;

  // Game-winner marker (walkoff)
  isGameWinner?: boolean;
  isOT?: boolean;
  otNum?: number;
}

// PlayLine-shape kept for consumer compatibility with the existing useLiveGame
// reducer logic. cs/ds are derived consumer-side from the event stream — they
// are computed once at the end of synthesis to embed the running score per line.
export interface InlinePlayLine extends InlineEvent {
  cs: number;  // HOME running score AFTER this event
  ds: number;  // AWAY running score AFTER this event
}

// Per-quarter, per-player budgets after distribution from game totals.
export interface PlayerQuarterBudget {
  fg2: number;   // 2pt makes
  fg3: number;   // 3pt makes
  fg4: number;   // 4pt makes (rare)
  m2: number;    // 2pt misses
  m3: number;    // 3pt misses
  m4: number;    // 4pt misses
  ftm: number;   // FT makes
  ftmiss: number;
  ast: number;
  orb: number;
  drb: number;
  stl: number;
  blk: number;
  tov: number;
  pf: number;
  sec: number;   // seconds-on-floor in this quarter (for sub timing)
}

export interface QuarterBudgets {
  q: number;
  homeByPid: Map<string, PlayerQuarterBudget>;
  awayByPid: Map<string, PlayerQuarterBudget>;
  homeTargetPts: number;
  awayTargetPts: number;
}

export interface SynthesizeInput {
  homeStats: import('../types').PlayerGameStats[];
  awayStats: import('../types').PlayerGameStats[];
  players: import('../../../types').NBAPlayer[];
  quarterScores: { home: number[]; away: number[] };
  otCount: number;
  gameWinner?: import('../types').GameResult['gameWinner'];
  homeTeamName?: string;
  awayTeamName?: string;
  timingConfig: import('../../../utils/gameClock').GameTimingConfig;
}

// Event sinks: NullSink (Fast-Mode, future use) discards events, ArraySink
// stores them. The synthesizer writes to a sink; the sink shape decouples the
// emission logic from the consumer.

import { InlineEvent, InlinePlayLine } from './types';

export interface EventSink {
  emit(event: InlineEvent): void;
  getEvents(): InlineEvent[];
}

export class ArraySink implements EventSink {
  private events: InlineEvent[] = [];

  emit(event: InlineEvent): void {
    this.events.push(event);
  }

  getEvents(): InlineEvent[] {
    return this.events;
  }
}

export class NullSink implements EventSink {
  emit(_event: InlineEvent): void {
    // Discarded — Fast Mode does not need PBP history
  }

  getEvents(): InlineEvent[] {
    return [];
  }
}

// Derive running scores (cs = HOME, ds = AWAY) consumer-side from the event
// stream. This is the ZenGM-pattern: PBP entries don't store cs/ds at emit
// time; instead the consumer reconstructs the running score by replaying the
// pts contribution of each event. AC1/AC2 are guaranteed by construction:
// the final cs/ds == sum of all event.pts per team, which == the engine's
// box-score IF the synthesizer's event budgets sum to the quarter targets.
export function attachRunningScores(events: InlineEvent[]): InlinePlayLine[] {
  let cs = 0;
  let ds = 0;
  return events.map(ev => {
    if (ev.tm === 'HOME') cs += ev.pts;
    else if (ev.tm === 'AWAY') ds += ev.pts;
    return { ...ev, cs, ds };
  });
}

// InlinePbpSynthesizer — Skeleton (Phase 1).
// Produces an InlinePlayLine[] from a finished game's box-score, in a
// ZenGM-inspired style: each event is emitted with its scoring contribution,
// and the running cs/ds is derived consumer-side from the event stream.
//
// This file is intentionally minimal in Phase 1 — actual budget distribution
// and event emission come in Phases 2 and 3.

import { ArraySink, attachRunningScores } from './eventSink';
import { InlinePlayLine, SynthesizeInput } from './types';
import { distributeBudgets } from './budgetDistributor';
import { emitQuarter } from './eventEmitter';
import { getPeriodLabel, getPeriodStartClock } from '../../../utils/gameClock';

export async function synthesizeInlinePbp(input: SynthesizeInput): Promise<InlinePlayLine[]> {
  const sink = new ArraySink();
  const { quarterScores, otCount, timingConfig } = input;
  const totalPeriods = timingConfig.numQuarters + otCount;

  // Phase 2: distribute total stats into per-quarter buckets that exactly
  // sum to quarterScores per team.
  const quarterBudgets = distributeBudgets(input);

  // Jump-ball event (no scoring, just narrative anchor)
  sink.emit({
    id: 'jumpball',
    type: 'jumpball',
    q: 1,
    period: getPeriodLabel(1, timingConfig.numQuarters),
    clock: getPeriodStartClock(1, timingConfig),
    gs: 0,
    time: `${getPeriodLabel(1, timingConfig.numQuarters)} ${getPeriodStartClock(1, timingConfig)}`,
    tm: 'HOME',           // overridden by emitQuarter when actual tip is decided
    possession: 'HOME',
    lineupHOME: [],       // filled by emitQuarter
    lineupAWAY: [],
    pts: 0,
    desc: 'Jumpball!',
  });

  // Phase 3: emit possession-events per quarter, exhausting budgets exactly.
  for (let q = 1; q <= totalPeriods; q++) {
    emitQuarter(sink, q, quarterBudgets[q - 1], input);
  }

  // Attach running scores (cs/ds) consumer-side.
  return attachRunningScores(sink.getEvents());
}

// Distributes total per-player stats into per-quarter buckets that
// EXACTLY sum to quarterScores per team. Strict invariant:
//   Σ_q (pts contributed by HOME players in q) === quarterScores.home[q]
//   Σ_q (pts contributed by AWAY players in q) === quarterScores.away[q]
//
// Approach: minutes-weighted distribution + integer-leftover correction pass.
// Each player's quarter shot/stat budget is proportional to their share of
// total team scoring + minutes in that quarter, then a correction loop nudges
// integer rounding so per-quarter pts hit the exact target.

import { QuarterBudgets, PlayerQuarterBudget, SynthesizeInput } from './types';
import { PlayerGameStats } from '../types';

const PLAYER_BUDGET_KEYS: (keyof PlayerQuarterBudget)[] = [
  'fg2', 'fg3', 'fg4', 'm2', 'm3', 'm4',
  'ftm', 'ftmiss', 'ast', 'orb', 'drb',
  'stl', 'blk', 'tov', 'pf', 'sec',
];

function emptyBudget(): PlayerQuarterBudget {
  return {
    fg2: 0, fg3: 0, fg4: 0, m2: 0, m3: 0, m4: 0,
    ftm: 0, ftmiss: 0, ast: 0, orb: 0, drb: 0,
    stl: 0, blk: 0, tov: 0, pf: 0, sec: 0,
  };
}

function statTotals(stat: PlayerGameStats): PlayerQuarterBudget {
  const fgm = stat.fgm ?? 0;
  const fga = stat.fga ?? 0;
  const fg3m = stat.threePm ?? 0;
  const fg3a = stat.threePa ?? 0;
  const fg4m = stat.fourPm ?? 0;
  const fg4a = stat.fourPa ?? 0;
  const fg2m = fgm - fg3m - fg4m;
  const fg2a = fga - fg3a - fg4a;
  const ftm = stat.ftm ?? 0;
  const fta = stat.fta ?? 0;

  return {
    fg2: Math.max(0, fg2m),
    fg3: Math.max(0, fg3m),
    fg4: Math.max(0, fg4m),
    m2: Math.max(0, fg2a - fg2m),
    m3: Math.max(0, fg3a - fg3m),
    m4: Math.max(0, fg4a - fg4m),
    ftm: Math.max(0, ftm),
    ftmiss: Math.max(0, fta - ftm),
    ast: stat.ast ?? 0,
    orb: stat.orb ?? 0,
    drb: stat.drb ?? 0,
    stl: stat.stl ?? 0,
    blk: stat.blk ?? 0,
    tov: stat.tov ?? 0,
    pf: stat.pf ?? 0,
    sec: Math.round((stat.min ?? 0) * 60),
  };
}

function quartersFractions(numQuarters: number, otCount: number): number[] {
  // Equal-weight split across regulation + OT periods. This is the simplest
  // distribution that still satisfies AC1/AC2 because the integer-correction
  // pass below pins per-quarter pts to the target. Refinement (pace-weighted)
  // is a Phase-3 polish.
  const total = numQuarters + otCount;
  return Array.from({ length: total }, () => 1 / total);
}

function splitInteger(total: number, fractions: number[]): number[] {
  // Largest-remainder method: split `total` into len(fractions) integers
  // whose sum equals `total`.
  if (total === 0) return fractions.map(() => 0);
  const raw = fractions.map(f => total * f);
  const floored = raw.map(r => Math.floor(r));
  let remainder = total - floored.reduce((s, n) => s + n, 0);
  const remainders = raw
    .map((r, i) => ({ i, frac: r - Math.floor(r) }))
    .sort((a, b) => b.frac - a.frac);
  for (let k = 0; k < remainder && k < remainders.length; k++) {
    floored[remainders[k].i]++;
  }
  return floored;
}

function pointsOf(b: PlayerQuarterBudget): number {
  return b.fg2 * 2 + b.fg3 * 3 + b.fg4 * 4 + b.ftm;
}

// Correct a side's per-quarter budgets so that Σ pts === target per quarter.
// Strategy: shift fg2-makes between quarters (1 fg2 = 2 pts). If 1-pt drift
// remains, swap an ftm. Operates only on integer movements between quarters
// of the SAME team — total per-player stats are preserved.
function reconcilePerQuarterTotals(
  teamByPid: Map<string, PlayerQuarterBudget>[],
  targets: number[],
): void {
  const Q = teamByPid.length;

  // Step 1: compute current per-quarter pts
  const current = teamByPid.map(qMap => {
    let pts = 0;
    qMap.forEach(b => { pts += pointsOf(b); });
    return pts;
  });

  // Step 2: iteratively move fg2 / ftm between quarters to fix deltas.
  // Heavy quarters donate, light quarters receive. Movements happen at the
  // player level (preserves per-player totals).
  const maxPasses = 200;
  for (let pass = 0; pass < maxPasses; pass++) {
    let anyMoved = false;
    for (let qSrc = 0; qSrc < Q; qSrc++) {
      const srcDelta = current[qSrc] - targets[qSrc]; // > 0 = quarter has too many pts
      if (srcDelta <= 0) continue;

      for (let qDst = 0; qDst < Q; qDst++) {
        if (qSrc === qDst) continue;
        const dstDelta = current[qDst] - targets[qDst]; // < 0 = quarter is short
        if (dstDelta >= 0) continue;

        // Find a player who has fg2 in qSrc AND can absorb fg2 in qDst.
        // "Can absorb" just means we add to qDst — totals stay the same.
        const movePts = Math.min(srcDelta, -dstDelta);

        let pidToMove: string | null = null;
        let unit: 'fg2' | 'fg3' | 'ftm' = 'fg2';
        let unitPts = 2;

        // Prefer fg2 swaps (smallest granularity that hits both odd & even).
        if (movePts >= 2) {
          for (const [pid, b] of teamByPid[qSrc]) {
            if (b.fg2 > 0) { pidToMove = pid; unit = 'fg2'; unitPts = 2; break; }
          }
        }
        if (!pidToMove && movePts >= 1) {
          // 1-pt drift → use ftm swap
          for (const [pid, b] of teamByPid[qSrc]) {
            if (b.ftm > 0) { pidToMove = pid; unit = 'ftm'; unitPts = 1; break; }
          }
        }
        if (!pidToMove && movePts >= 3) {
          for (const [pid, b] of teamByPid[qSrc]) {
            if (b.fg3 > 0) { pidToMove = pid; unit = 'fg3'; unitPts = 3; break; }
          }
        }

        if (!pidToMove) continue;

        const srcBudget = teamByPid[qSrc].get(pidToMove)!;
        let dstBudget = teamByPid[qDst].get(pidToMove);
        if (!dstBudget) {
          dstBudget = emptyBudget();
          teamByPid[qDst].set(pidToMove, dstBudget);
        }
        srcBudget[unit]--;
        dstBudget[unit]++;
        current[qSrc] -= unitPts;
        current[qDst] += unitPts;
        anyMoved = true;
        break;
      }
    }
    if (!anyMoved) break;
  }
}

function distributeOneSide(
  stats: PlayerGameStats[],
  quarterTargets: number[],
  fractions: number[],
): Map<string, PlayerQuarterBudget>[] {
  const Q = quarterTargets.length;
  const result: Map<string, PlayerQuarterBudget>[] = Array.from({ length: Q }, () => new Map());

  for (const s of stats) {
    const totals = statTotals(s);
    for (const key of PLAYER_BUDGET_KEYS) {
      const splits = splitInteger(totals[key], fractions);
      for (let q = 0; q < Q; q++) {
        let qb = result[q].get(s.playerId);
        if (!qb) {
          qb = emptyBudget();
          result[q].set(s.playerId, qb);
        }
        qb[key] = splits[q];
      }
    }
  }

  // Pin per-quarter pts to exact targets
  reconcilePerQuarterTotals(result, quarterTargets);

  return result;
}

export function distributeBudgets(input: SynthesizeInput): QuarterBudgets[] {
  const { homeStats, awayStats, quarterScores, otCount, timingConfig } = input;
  const totalPeriods = timingConfig.numQuarters + otCount;
  const fractions = quartersFractions(timingConfig.numQuarters, otCount);

  const homeTargets = Array.from({ length: totalPeriods }, (_, i) => quarterScores.home[i] ?? 0);
  const awayTargets = Array.from({ length: totalPeriods }, (_, i) => quarterScores.away[i] ?? 0);

  const homePerQ = distributeOneSide(homeStats, homeTargets, fractions);
  const awayPerQ = distributeOneSide(awayStats, awayTargets, fractions);

  return Array.from({ length: totalPeriods }, (_, q) => ({
    q: q + 1,
    homeByPid: homePerQ[q],
    awayByPid: awayPerQ[q],
    homeTargetPts: homeTargets[q],
    awayTargetPts: awayTargets[q],
  }));
}

// Emits events for one quarter by exhaustively consuming the player budgets.
// Strict invariant: every stat in the budget becomes exactly one event;
// every event with pts > 0 corresponds to a single fg2/fg3/fg4/ftm decrement.
// → Σ(pts of HOME events in quarter q) === Σ(fg2*2 + fg3*3 + fg4*4 + ftm)
//   of all HOME players' q-budgets === quarterScores.home[q] (after the
//   budgetDistributor's reconcile pass).

import { ArraySink } from './eventSink';
import {
  InlineEvent,
  PlayerQuarterBudget,
  QuarterBudgets,
  SynthesizeInput,
} from './types';
import { PlayerPool, TeamId } from '../live/playback/possessionTypes';
import { RotationService } from '../live/playback/rotationService';
import {
  getPeriodDurationSeconds,
  getPeriodLabel,
  getPeriodStartSeconds,
} from '../../../utils/gameClock';
import {
  generateMadeNarrative,
  generateMissNarrative,
  generateReboundNarrative,
  generateTovNarrative,
  generateBlockNarrative,
} from '../live/playback/badgeCommentary';

interface PendingShot {
  pid: string;
  team: TeamId;
  kind: 'made2' | 'made3' | 'made4' | 'miss2' | 'miss3' | 'miss4';
}

interface PendingFoul {
  foulerPid: string;
  foulerTeam: TeamId;
  victimPid?: string;
  victimTeam?: TeamId;
  fts: { made: boolean }[];
}

function buildPool(
  byPid: Map<string, PlayerQuarterBudget>,
  stats: import('../types').PlayerGameStats[],
  players: import('../../../types').NBAPlayer[],
  tm: TeamId,
): PlayerPool[] {
  return stats.filter(Boolean).map(stat => {
    const b = byPid.get(stat.playerId) ?? null;
    const player = players.find(p => p.internalId?.toString() === stat.playerId) || players[0];
    return {
      n: stat.name,
      fn: stat.name,
      id: stat.playerId,
      imgURL: player?.imgURL,
      tm,
      min: (b?.sec ?? 0) / 60,
      pos: (player?.pos as 'G' | 'F' | 'C') ?? 'C',
      fg2: b?.fg2 ?? 0,
      fg3: b?.fg3 ?? 0,
      fg4: b?.fg4 ?? 0,
      m2: b?.m2 ?? 0,
      m3: b?.m3 ?? 0,
      m4: b?.m4 ?? 0,
      ftm: b?.ftm ?? 0,
      ftmiss: b?.ftmiss ?? 0,
      ast: b?.ast ?? 0,
      orb: b?.orb ?? 0,
      drb: b?.drb ?? 0,
      stl: b?.stl ?? 0,
      blk: b?.blk ?? 0,
      tov: b?.tov ?? 0,
      pf: b?.pf ?? 0,
    };
  });
}

function shotsFromBudgets(
  byPid: Map<string, PlayerQuarterBudget>,
  team: TeamId,
): PendingShot[] {
  const shots: PendingShot[] = [];
  for (const [pid, b] of byPid) {
    for (let i = 0; i < b.fg2; i++) shots.push({ pid, team, kind: 'made2' });
    for (let i = 0; i < b.fg3; i++) shots.push({ pid, team, kind: 'made3' });
    for (let i = 0; i < b.fg4; i++) shots.push({ pid, team, kind: 'made4' });
    for (let i = 0; i < b.m2; i++) shots.push({ pid, team, kind: 'miss2' });
    for (let i = 0; i < b.m3; i++) shots.push({ pid, team, kind: 'miss3' });
    for (let i = 0; i < b.m4; i++) shots.push({ pid, team, kind: 'miss4' });
  }
  return shots;
}

// Build interleaved possession sequence. We alternate HOME/AWAY trying to
// drain shot lists; misses with offensive-rebound budget keep possession.
// FTs and TOVs are inserted alongside misses/fouls. Plain alternation is
// adequate for AC1/AC2 — pacing realism is polish for Phase 4.
function interleaveShots(home: PendingShot[], away: PendingShot[]): PendingShot[] {
  const out: PendingShot[] = [];
  let hi = 0, ai = 0;
  let turn: TeamId = 'HOME';
  while (hi < home.length || ai < away.length) {
    if (turn === 'HOME' && hi < home.length) {
      out.push(home[hi++]);
      turn = 'AWAY';
    } else if (turn === 'AWAY' && ai < away.length) {
      out.push(away[ai++]);
      turn = 'HOME';
    } else if (hi < home.length) {
      out.push(home[hi++]);
    } else if (ai < away.length) {
      out.push(away[ai++]);
    }
  }
  return out;
}

function findPool(pool: PlayerPool[], pid: string): PlayerPool | undefined {
  return pool.find(p => p.id === pid);
}

function consumeAssist(
  byPid: Map<string, PlayerQuarterBudget>,
  pool: PlayerPool[],
  scorerPid: string,
): PlayerPool | undefined {
  // Pick a teammate with ast budget remaining (~60% of makes get assists in NBA)
  if (Math.random() > 0.6) return undefined;
  for (const p of pool) {
    if (p.id === scorerPid) continue;
    const b = byPid.get(p.id);
    if (b && b.ast > 0) {
      b.ast--;
      return p;
    }
  }
  return undefined;
}

function consumeRebound(
  ownByPid: Map<string, PlayerQuarterBudget>,
  oppByPid: Map<string, PlayerQuarterBudget>,
  ownPool: PlayerPool[],
  oppPool: PlayerPool[],
): { rebounder: PlayerPool; isOff: boolean } | undefined {
  // Prefer defensive rebound (opp team). Fallback to offensive if opp has no drb.
  for (const p of oppPool) {
    const b = oppByPid.get(p.id);
    if (b && b.drb > 0) {
      b.drb--;
      return { rebounder: p, isOff: false };
    }
  }
  for (const p of ownPool) {
    const b = ownByPid.get(p.id);
    if (b && b.orb > 0) {
      b.orb--;
      return { rebounder: p, isOff: true };
    }
  }
  return undefined;
}

function consumeBlock(
  oppByPid: Map<string, PlayerQuarterBudget>,
  oppPool: PlayerPool[],
): PlayerPool | undefined {
  if (Math.random() > 0.18) return undefined;
  for (const p of oppPool) {
    const b = oppByPid.get(p.id);
    if (b && b.blk > 0) {
      b.blk--;
      return p;
    }
  }
  return undefined;
}

function consumeSteal(
  oppByPid: Map<string, PlayerQuarterBudget>,
  oppPool: PlayerPool[],
): PlayerPool | undefined {
  if (Math.random() > 0.55) return undefined;
  for (const p of oppPool) {
    const b = oppByPid.get(p.id);
    if (b && b.stl > 0) {
      b.stl--;
      return p;
    }
  }
  return undefined;
}

function pidOfFirst<T extends { pid: string }>(arr: T[]): string | undefined {
  return arr[0]?.pid;
}

function pickTov(byPid: Map<string, PlayerQuarterBudget>): string | undefined {
  for (const [pid, b] of byPid) if (b.tov > 0) return pid;
  return undefined;
}

function pickFoul(byPid: Map<string, PlayerQuarterBudget>): string | undefined {
  for (const [pid, b] of byPid) if (b.pf > 0) return pid;
  return undefined;
}

function pickFtVictim(byPid: Map<string, PlayerQuarterBudget>): string | undefined {
  for (const [pid, b] of byPid) if (b.ftm + b.ftmiss > 0) return pid;
  return undefined;
}

function makeId(q: number, idx: number, suffix: string): string {
  return `q${q}-${idx}-${suffix}`;
}

export function emitQuarter(
  sink: ArraySink,
  q: number,
  budgets: QuarterBudgets,
  input: SynthesizeInput,
): void {
  const { homeStats, awayStats, players, timingConfig, otCount } = input;
  const qDur = getPeriodDurationSeconds(q, timingConfig);
  const qStartGs = getPeriodStartSeconds(q, timingConfig);
  const period = getPeriodLabel(q, timingConfig.numQuarters);
  const isOT = q > timingConfig.numQuarters;
  const otNum = isOT ? q - timingConfig.numQuarters : undefined;

  const homePool = buildPool(budgets.homeByPid, homeStats, players, 'HOME');
  const awayPool = buildPool(budgets.awayByPid, awayStats, players, 'AWAY');

  const homeShots = shotsFromBudgets(budgets.homeByPid, 'HOME');
  const awayShots = shotsFromBudgets(budgets.awayByPid, 'AWAY');
  const sequence = interleaveShots(homeShots, awayShots);

  const totalSlots = sequence.length + 1; // +1 buffer at end
  let idx = 0;

  // Helper: assign clock for this event based on its index in the sequence.
  // Distributes evenly across the quarter duration with mild jitter.
  const clockForIdx = (i: number): { gs: number; clock: string } => {
    const frac = totalSlots > 1 ? i / Math.max(1, totalSlots - 1) : 0;
    const elapsed = Math.min(qDur - 0.5, Math.max(0.5, frac * qDur));
    const gs = qStartGs + elapsed;
    const remaining = Math.max(0, qDur - elapsed);
    const mm = Math.floor(remaining / 60);
    const ss = Math.floor(remaining % 60);
    const clock = `${mm}:${ss.toString().padStart(2, '0')}`;
    return { gs, clock };
  };

  const lineupAt = (gs: number, diff: number) => ({
    home: RotationService.getLineupAtTime(homePool, gs, diff),
    away: RotationService.getLineupAtTime(awayPool, gs, -diff),
  });

  // Period-start label (Q2+ only; Q1 is anchored by jumpball event)
  if (q > 1) {
    const startGs = qStartGs - 0.1;
    sink.emit({
      id: makeId(q, -1, isOT ? 'ot_start' : 'q_start'),
      type: 'period_end',
      q, period,
      clock: q === timingConfig.numQuarters + 1 || isOT
        ? `${Math.floor(qDur / 60)}:${(qDur % 60).toString().padStart(2, '0')}`
        : `${Math.floor(qDur / 60)}:00`,
      gs: startGs,
      time: `${period} start`,
      tm: 'HOME',
      possession: 'HOME',
      lineupHOME: [],
      lineupAWAY: [],
      pts: 0,
      desc: isOT ? `Overtime ${otNum}! Here we go!!` : `${period} quarter underway.`,
      isOT,
      otNum,
    });
  }

  let runningHomePts = 0;
  let runningAwayPts = 0;

  for (const shot of sequence) {
    const { gs, clock } = clockForIdx(idx);
    const diff = runningHomePts - runningAwayPts;
    const { home: homeLineup, away: awayLineup } = lineupAt(gs, diff);

    const ownByPid = shot.team === 'HOME' ? budgets.homeByPid : budgets.awayByPid;
    const oppByPid = shot.team === 'HOME' ? budgets.awayByPid : budgets.homeByPid;
    const ownPool = shot.team === 'HOME' ? homeLineup : awayLineup;
    const oppPool = shot.team === 'HOME' ? awayLineup : homeLineup;
    const fullOwnPool = shot.team === 'HOME' ? homePool : awayPool;

    const shooter = findPool(fullOwnPool, shot.pid);
    if (!shooter) { idx++; continue; }

    const isMade = shot.kind.startsWith('made');
    const is3 = shot.kind === 'made3' || shot.kind === 'miss3';
    const is4 = shot.kind === 'made4' || shot.kind === 'miss4';
    const pts = isMade ? (is4 ? 4 : is3 ? 3 : 2) : 0;

    if (isMade) {
      const assister = consumeAssist(ownByPid, ownPool, shooter.id);
      const desc = generateMadeNarrative(shooter, pts, assister ?? null, false, oppPool);
      sink.emit({
        id: makeId(q, idx, 'made'),
        type: 'made_fg',
        q, period, clock, gs,
        time: `${period} ${clock}`,
        tm: shot.team,
        possession: shot.team,
        lineupHOME: homeLineup,
        lineupAWAY: awayLineup,
        player: shooter,
        astPlayer: assister,
        pts,
        is3, is4,
        desc,
      });
      if (shot.team === 'HOME') runningHomePts += pts; else runningAwayPts += pts;
    } else {
      const blocker = consumeBlock(oppByPid, oppPool);
      const missDesc = generateMissNarrative(shooter, is3 || is4, oppPool);
      sink.emit({
        id: makeId(q, idx, 'miss'),
        type: 'miss_fg',
        q, period, clock, gs,
        time: `${period} ${clock}`,
        tm: shot.team,
        possession: shot.team,
        lineupHOME: homeLineup,
        lineupAWAY: awayLineup,
        player: shooter,
        blocker,
        pts: 0,
        is3, is4,
        desc: missDesc,
      });
      if (blocker) {
        sink.emit({
          id: makeId(q, idx, 'blk'),
          type: 'foul', // type 'blk' isn't in PlayLine schema; rendered as defensive event
          q, period, clock,
          gs: gs + 0.01,
          time: `${period} ${clock}`,
          tm: blocker.tm,
          possession: shot.team,
          lineupHOME: homeLineup,
          lineupAWAY: awayLineup,
          player: blocker,
          pts: 0,
          desc: generateBlockNarrative(blocker, shooter),
        });
      }
      const reb = consumeRebound(ownByPid, oppByPid, ownPool, oppPool);
      if (reb) {
        sink.emit({
          id: makeId(q, idx, 'reb'),
          type: 'reb',
          q, period, clock,
          gs: gs + 0.02,
          time: `${period} ${clock}`,
          tm: reb.rebounder.tm,
          possession: reb.isOff ? shot.team : (shot.team === 'HOME' ? 'AWAY' : 'HOME'),
          lineupHOME: homeLineup,
          lineupAWAY: awayLineup,
          player: reb.rebounder,
          pts: 0,
          isOffReb: reb.isOff,
          desc: generateReboundNarrative(reb.rebounder, reb.isOff, false),
        });
      }
    }

    idx++;
  }

  // Drain remaining FT budgets at end-of-quarter. These come from undecremented
  // ftm/ftmiss that the shot loop didn't pair with foul events (we keep the
  // implementation simple: FTs ride at the tail). Each FT contributes its own
  // pts; the budget reconciler already ensured Σ pts matches the target.
  const drainFTsForTeam = (team: TeamId, byPid: Map<string, PlayerQuarterBudget>, pool: PlayerPool[]) => {
    for (const p of pool) {
      const b = byPid.get(p.id);
      if (!b) continue;
      const totalFt = b.ftm + b.ftmiss;
      if (totalFt === 0) continue;
      const { gs, clock } = clockForIdx(idx);
      const diff = runningHomePts - runningAwayPts;
      const lineup = lineupAt(gs, diff);

      const fouler = pickFoul(team === 'HOME' ? budgets.awayByPid : budgets.homeByPid);
      const foulerPlayer = fouler
        ? findPool(team === 'HOME' ? awayPool : homePool, fouler)
        : (team === 'HOME' ? awayPool[0] : homePool[0]);
      if (foulerPlayer) {
        const fb = (team === 'HOME' ? budgets.awayByPid : budgets.homeByPid).get(foulerPlayer.id);
        if (fb && fb.pf > 0) fb.pf--;
        sink.emit({
          id: makeId(q, idx, 'foul'),
          type: 'foul',
          q, period, clock, gs,
          time: `${period} ${clock}`,
          tm: foulerPlayer.tm,
          possession: team,
          lineupHOME: lineup.home,
          lineupAWAY: lineup.away,
          player: foulerPlayer,
          pts: 0,
          desc: `Foul called on ${foulerPlayer.n}.`,
        });
      }

      for (let i = 0; i < totalFt; i++) {
        const isMake = b.ftm > 0;
        if (isMake) b.ftm--;
        else b.ftmiss--;
        const ftIdx = i + 1;
        const { gs: ftGs, clock: ftClock } = clockForIdx(idx);
        sink.emit({
          id: makeId(q, idx, `ft${i}`),
          type: 'ft',
          q, period, clock: ftClock,
          gs: ftGs + 0.1 * ftIdx,
          time: `${period} ${ftClock}`,
          tm: team,
          possession: team,
          lineupHOME: lineup.home,
          lineupAWAY: lineup.away,
          player: p,
          pts: isMake ? 1 : 0,
          isMake,
          desc: isMake ? `${p.n} free throw GOOD.` : `${p.n} free throw MISSED.`,
        });
        if (isMake) {
          if (team === 'HOME') runningHomePts += 1;
          else runningAwayPts += 1;
        }
      }
      idx++;
    }
  };
  drainFTsForTeam('HOME', budgets.homeByPid, homePool);
  drainFTsForTeam('AWAY', budgets.awayByPid, awayPool);

  // Drain remaining tov budgets (each tov === one tov event)
  const drainTovs = (team: TeamId, byPid: Map<string, PlayerQuarterBudget>, pool: PlayerPool[]) => {
    const oppByPid = team === 'HOME' ? budgets.awayByPid : budgets.homeByPid;
    const oppPool = team === 'HOME' ? awayPool : homePool;
    for (const p of pool) {
      const b = byPid.get(p.id);
      if (!b) continue;
      while (b.tov > 0) {
        b.tov--;
        const { gs, clock } = clockForIdx(idx);
        const diff = runningHomePts - runningAwayPts;
        const lineup = lineupAt(gs, diff);
        const stealer = consumeSteal(oppByPid, oppPool);
        sink.emit({
          id: makeId(q, idx, 'tov'),
          type: 'tov',
          q, period, clock, gs,
          time: `${period} ${clock}`,
          tm: team,
          possession: team,
          lineupHOME: lineup.home,
          lineupAWAY: lineup.away,
          player: p,
          stealer,
          pts: 0,
          desc: generateTovNarrative(p, stealer ?? null),
        });
        idx++;
      }
    }
  };
  drainTovs('HOME', budgets.homeByPid, homePool);
  drainTovs('AWAY', budgets.awayByPid, awayPool);

  // End-of-quarter buzzer marker for OT bridge / final
  if (q === timingConfig.numQuarters + otCount) {
    sink.emit({
      id: makeId(q, idx, 'final'),
      type: 'game_end',
      q, period,
      clock: '0:00',
      gs: qStartGs + qDur,
      time: `${period} 0:00`,
      tm: 'HOME',
      possession: 'HOME',
      lineupHOME: [],
      lineupAWAY: [],
      pts: 0,
      desc: 'The buzzer sounds.',
    });
  }
}

