// Hard per-player cap: no player can exceed 48 min (reg) or 53/58 (OT).
// Short-handed teams (< 9 players): tighter cap so role players don't marathon 48 min
// when the star and 2 others draw high minutesMult. E.g. 8 players → max ~41 min each.
const perPlayerMax = rotation.length < 9
  ? Math.min(42 + otCount * overtimeDuration, Math.floor((totalMinuteBudget / rotation.length) * 1.35))
  : regulationLength + otCount * overtimeDuration;
for (let iter = 0; iter < 4; iter++) {
  if (!playerMinutes.some(m => m > perPlayerMax + 0.01)) break;
  playerMinutes = playerMinutes.map(m => Math.min(perPlayerMax, m));
  const cappedTotal = playerMinutes.reduce((a, b) => a + b, 0) || 1;
  playerMinutes = playerMinutes.map(m => m * (totalMinuteBudget / cappedTotal));
}

input.new_string:
// Hard per-player cap: no player can exceed game length (reg + OT). Short-
// handed teams (< 9 players) get a tighter cap so role players don't marathon
// when the star and 2 others draw high minutesMult.
const perPlayerMax = rotation.length < 9
  ? Math.min(regulationLength + otCount * overtimeDuration, Math.floor((totalMinuteBudget / rotation.length) * 1.35))
  : regulationLength + otCount * overtimeDuration;

// Cap + redistribute excess only to players still under the cap. Previously
// the loop did a uniform re-normalize after capping which pushed capped
// players right back over (Euro 40-min games: Russell ended at 41.35 despite
// cap=40 — re-normalize scaled all 12 players ×(200/cappedTotal>1)).
for (let iter = 0; iter < 6; iter++) {
  const overIdx = playerMinutes
    .map((m, i) => (m > perPlayerMax + 0.01 ? i : -1))
    .filter(i => i >= 0);
  if (overIdx.length === 0) break;

  let excess = 0;
  for (const i of overIdx) {
    excess += playerMinutes[i] - perPlayerMax;
    playerMinutes[i] = perPlayerMax;
  }

  // Donate excess to under-cap players, weighted by their current minutes
  // (so starters absorb more than deep-bench scrubs). If every other player
  // is at cap (impossible for Euro 40min × 12 ≥ budget, but defensive), drop
  // the remainder rather than reinflate capped values.
  const underIdx = playerMinutes
    .map((m, i) => (m < perPlayerMax - 0.01 ? i : -1))
    .filter(i => i >= 0);
  if (underIdx.length === 0) break;

  const underWeightSum = underIdx.reduce((s, i) => s + playerMinutes[i], 0) || underIdx.length;
  for (const i of underIdx) {
    const share = playerMinutes[i] / underWeightSum;
    playerMinutes[i] = Math.min(perPlayerMax, playerMinutes[i] + excess * share);
  }
}

