              className="mt-4 w-full bg-amber-500 hover:bg-amber-400 text-slate-950 font-black uppercase tracking-widest py-2 rounded-xl text-xs"
            >
              Got It
            </button>
          </div>
        </div>
      )}
    </>
  );
};

