// Fetches Euroleague historical season data (1995-96 → 2024-25) from the
// nba-store-data gist. Module-level cache so repeated mounts don't re-hit
// the network. Used by EuroleagueHistoryView (and any future TeamHistoryView
// crosslookup like "Real Madrid · 11 EL Titles").

const URL = 'https://raw.githubusercontent.com/aljohnpolyglot/nba-store-data/refs/heads/main/euroleaguehistoryfull';

export interface EuroleagueSeason {
  Season_Title?: string;
  Wikipedia_URL?: string;
  League?: string;
  Season?: string;            // "2024–25" (en-dash)
  Duration?: string;
  Games_played?: string;
  Teams?: string;
  Top_seed?: string;
  Season_MVP?: string;
  Regular_Season_MVP?: string;
  Champions?: string;         // "Real Madrid (11th title)"
  Runnersup?: string;
  Third_place?: string;
  Fourth_place?: string;
  Semifinalists?: string;
  Final_Four_MVP?: string;
  Finals_MVP?: string;
  Playoffs_MVP?: string;
  Playin_MVP?: string;
  Top_16_MVP?: string;
  Alphonso_Ford_Trophy?: string;
  Best_Defender?: string;
  Rising_Star?: string;
  Coach_of_the_Year?: string;
  Top_scorer?: string;
  Points?: string;
  Rebounds?: string;
  Assists?: string;
  Steals?: string;
  Blocks?: string;
  Index_Rating?: string;
  Biggest_home_win?: string;
  Biggest_away_win?: string;
  Highest_scoring?: string;
  Winning_streak?: string;
  Losing_streak?: string;
  Highest_attendance?: string;
  Lowest_attendance?: string;
  Attendance?: string;
  Average_attendance?: string;
  Dates?: string;
  Sport?: string;
}

let cache: EuroleagueSeason[] | null = null;
let inflight: Promise<EuroleagueSeason[]> | null = null;

export async function fetchEuroleagueHistory(): Promise<EuroleagueSeason[]> {
  if (cache) return cache;
  if (inflight) return inflight;
  inflight = fetch(URL)
    .then(r => {
      if (!r.ok) throw new Error(`Euroleague history fetch failed: ${r.status}`);
      return r.json();
    })
    .then((arr: EuroleagueSeason[]) => {
      cache = Array.isArray(arr) ? arr : [];
      inflight = null;
      return cache;
    })
    .catch(err => {
      inflight = null;
      throw err;
    });
  return inflight;
}

/** Strip "(11th title)" / "(2nd title)" decorations and trailing whitespace. */
export function cleanChampionName(raw: string | undefined): string {
  if (!raw) return '';
  return raw.replace(/\s*\([^)]*\)\s*$/, '').trim();
}

/** Strip the parenthetical team-affiliation tail e.g. "Joe Arlauckas (Real Madrid)" → "Joe Arlauckas". */
export function cleanPlayerName(raw: string | undefined): string {
  if (!raw) return '';
  return raw.replace(/\s*\([^)]*\)\s*$/, '').trim();
}

import React, { useEffect, useMemo, useState } from 'react';
import { Trophy, Loader, ExternalLink } from 'lucide-react';
import {
  fetchEuroleagueHistory,
  cleanChampionName,
  cleanPlayerName,
  EuroleagueSeason,
} from '../../data/euroleagueHistoryFetcher';

const STAR_AWARDS: Array<{ key: keyof EuroleagueSeason; label: string }> = [
  { key: 'Season_MVP',           label: 'Season MVP' },
  { key: 'Final_Four_MVP',       label: 'Final Four MVP' },
  { key: 'Finals_MVP',           label: 'Finals MVP' },
  { key: 'Playoffs_MVP',         label: 'Playoffs MVP' },
  { key: 'Playin_MVP',           label: 'Play-In MVP' },
  { key: 'Alphonso_Ford_Trophy', label: 'Top Scorer · Alphonso Ford' },
  { key: 'Best_Defender',        label: 'Best Defender' },
  { key: 'Rising_Star',          label: 'Rising Star' },
  { key: 'Coach_of_the_Year',    label: 'Coach of the Year' },
];

const STAT_LEADERS: Array<{ key: keyof EuroleagueSeason; label: string }> = [
  { key: 'Top_scorer',   label: 'Top Scorer' },
  { key: 'Points',       label: 'Points' },
  { key: 'Rebounds',     label: 'Rebounds' },
  { key: 'Assists',      label: 'Assists' },
  { key: 'Steals',       label: 'Steals' },
  { key: 'Blocks',       label: 'Blocks' },
  { key: 'Index_Rating', label: 'PIR Leader' },
];

export const EuroleagueHistoryView: React.FC = () => {
  const [seasons, setSeasons] = useState<EuroleagueSeason[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<EuroleagueSeason | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetchEuroleagueHistory()
      .then(data => { if (!cancelled) setSeasons(data); })
      .catch(e => { if (!cancelled) setError(String(e?.message ?? e)); });
    return () => { cancelled = true; };
  }, []);

  // Most-titled clubs: count champion appearances across all seasons
  const titlesByClub = useMemo(() => {
    if (!seasons) return [];
    const m = new Map<string, number>();
    seasons.forEach(s => {
      const champ = cleanChampionName(s.Champions);
      if (champ) m.set(champ, (m.get(champ) ?? 0) + 1);
    });
    return [...m.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8);
  }, [seasons]);

  if (error) {
    return (
      <div className="p-8 text-rose-400 text-sm">
        Could not load Euroleague history: {error}
      </div>
    );
  }
  if (!seasons) {
    return (
      <div className="p-8 text-slate-500 text-sm flex items-center gap-2">
        <Loader className="w-4 h-4 animate-spin" /> Loading Euroleague history…
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-6">
      <div className="rounded-3xl border border-slate-800 bg-slate-950 p-5"
