export function getActiveLeagueTeams(state: {
  teams: NBATeam[];
  nonNBATeams?: NonNBATeam[];
  userTeamId?: number | null;
  leagueStats?: { uiMode?: string | null };
  activeCompetitions?: Array<{ id: string; format?: string }>;
}): NBATeam[] {
  const uid = state.userTeamId;
  const isEuroIsolated = state.leagueStats?.uiMode === 'euro_isolated';

  // Euro-isolated setup flow: userTeamId is null until the GM picks their club.
  // Without this branch the franchise picker (TeamOffice/Home) falls through to
  // state.teams and shows the NBA 30 instead of the 18 Endesa clubs.
  if (isEuroIsolated && (uid == null || uid < 100)) {
    const primary =
      (state.activeCompetitions ?? []).find(c => c.format === 'regular-league')
      ?? (state.activeCompetitions ?? [])[0];
    const leagueById: Record<string, string> = {
      endesa: 'Endesa',
      euroleague: 'Euroleague',
    };
    const leagueName = primary ? leagueById[primary.id] : null;
    const clubs = (state.nonNBATeams ?? []).filter(
      t => leagueName ? t.league === leagueName : t.league === 'Endesa' || t.league === 'Euroleague',
    );
    const wrapped = clubs
      .map(t => resolveAnyTeam(t.tid, state.teams, state.nonNBATeams ?? []))
      .filter((t): t is NBATeam => t !== null);
    if (wrapped.length) return wrapped;
  }

  if (uid == null || uid < 100) return state.teams;
  const userTeam = (state.nonNBATeams ?? []).find(t => t.tid === uid);
  if (!userTeam) return state.teams;
  const sameLeague = (state.nonNBATeams ?? []).filter(t => t.league === userTeam.league);
  const wrapped = sameLeague
    .map(t => resolveAnyTeam(t.tid, state.teams, state.nonNBATeams ?? []))
    .filter((t): t is NBATeam => t !== null);
  return wrapped;
}

