 * calendar pivots on the 29th). Preseason games then begin Oct 2-4.
 * e.g. seasonYear=2026 → 2025-09-29
 *
 * Euro-isolated mode (Endesa starts Sep 28): default Sept 14 so the 14-day
 * camp/friendly window opens BEFORE the league does. Explicit
 * trainingCampMonth/Day overrides still win.
 */
export function getTrainingCampDate(seasonYear: number, stats?: TxnCalendar): Date {
  const isEuroIsolated = stats?.uiMode === 'euro_isolated';
  const m = stats?.trainingCampMonth ?? 9;
  const d = stats?.trainingCampDay ?? (isEuroIsolated ? 14 : 29);
  return new Date(Date.UTC(seasonYear - 1, m - 1, d));
}

