function historicalTeamRows(
  stats: NBAGMStat[],
  player: NBAPlayer,
  teams: { id: number; abbrev: string }[],
  nonNBATeams: { id: number; abbrev: string }[],
  statType: StatType,
  seasonLabel: number | 'career',
  age: number,
  teamFilter: string,
  passesTabFilter: (tid: number | undefined) => boolean,
): ComputedRow[] {
  // League-tab pre-filter: drop stats from teams outside the active tab.
  // Without this an Endesa view in a euro_isolated save would still surface
  // a player's NBA seasons (e.g. Luka 2024-25 LAL/DAL leaking into Liga Endesa).
  const filteredStats = stats.filter(s => passesTabFilter(s.tid));
  if (filteredStats.length === 0) return [];

  const lookupAbbrev = (tid: number): string | null => {
    const nba = teams.find(t2 => t2.id === tid);
    if (nba) return nba.abbrev;
    const ext = nonNBATeams.find(t2 => t2.id === tid);
    return ext ? ext.abbrev : null;
  };

  const byTid = new Map<number, NBAGMStat[]>();
  for (const s of filteredStats) {
    if (!byTid.has(s.tid)) byTid.set(s.tid, []);
    byTid.get(s.tid)!.push(s);
  }

  if (byTid.size <= 1) {
    const agg = stats.length > 1 ? aggregateStats(stats) : stats[0];
    if (agg.gp < 1) return [];
    const rowTeam = lookupAbbrev(agg.tid) ?? (agg.tid < 0 ? 'FA' : '?');
    if (teamFilter !== 'all' && rowTeam !== teamFilter) return [];
    return [toRow(player, agg, statType, seasonLabel, rowTeam, age)];
  }

  const result: ComputedRow[] = [];
  if (teamFilter === 'all') {
    const agg = aggregateStats(stats);
    if (agg.gp >= 1) result.push(toRow(player, agg, statType, seasonLabel, `${byTid.size}TM`, age));
  }
  for (const [tid, tidStats] of byTid) {
    const agg = tidStats.length > 1 ? aggregateStats(tidStats) : tidStats[0];
    if (agg.gp < 1) continue;
    const rowTeam = lookupAbbrev(tid) ?? (tid < 0 ? 'FA' : '?');
    if (teamFilter !== 'all' && rowTeam !== teamFilter) continue;
    result.push(toRow(player, agg, statType, seasonLabel, rowTeam, age));
  }
  return result;
}

