import React, { useMemo, useState } from 'react';
import { Plane, Hotel, Bus, Star } from 'lucide-react';
import type { TycoonState, TycoonTier } from '../../types/tycoon';
import { HelpIconPopover } from './HelpIconPopover';

interface Props {
  tycoon: TycoonState;
}

type Axis = 'hotel' | 'flight' | 'bus';

const TIER_DEFAULTS: Record<TycoonTier, Record<Axis, number>> = {
  S: { hotel: 5.0, flight: 5.0, bus: 5.0 },
  A: { hotel: 4.5, flight: 4.5, bus: 4.0 },
  B: { hotel: 4.0, flight: 4.0, bus: 3.5 },
  C: { hotel: 3.5, flight: 3.0, bus: 3.0 },
  D: { hotel: 3.0, flight: 2.5, bus: 2.5 },
};

const HOTEL_LABELS: Record<string, string> = {
  '0.5': 'Roadside motel',
  '1.0': 'Hostel',
  '1.5': 'Budget inn',
  '2.0': 'Standard 2★',
  '2.5': 'Comfort',
  '3.0': 'Mid-range 3★',
  '3.5': 'Superior 3★',
  '4.0': 'First-class 4★ — EuroLeague compliant',
  '4.5': 'Premium 4★ suites',
  '5.0': 'Luxury 5★ — single rooms, recovery suites',
};

const FLIGHT_LABELS: Record<string, string> = {
  '0.5': 'Economy commercial · long layovers',
  '1.0': 'Economy commercial',
  '1.5': 'Premium economy',
  '2.0': 'Premium economy · priority boarding',
  '2.5': 'Business class commercial',
  '3.0': 'Business class commercial · full team',
  '3.5': 'Group charter · shared',
  '4.0': 'Charter jet · standard config',
  '4.5': 'Charter jet · business config',
  '5.0': 'Private jet · custom team layout (Boeing 737BBJ)',
};

const BUS_LABELS: Record<string, string> = {
  '0.5': 'Public coach',
  '1.0': 'Standard coach',
  '1.5': 'Standard coach · onboard wifi',
  '2.0': 'Comfort coach',
  '2.5': 'Comfort coach · reclining seats',
  '3.0': 'Premium coach',
  '3.5': 'Luxury coach · panoramic',
  '4.0': 'Sleeper coach',
  '4.5': 'Custom team bus',
  '5.0': 'Custom luxury bus · galley + lounge',
};

const fmtKey = (v: number) => v.toFixed(1);

const Stars: React.FC<{ value: number }> = ({ value }) => {
  const full = Math.floor(value);
  const hasHalf = value - full >= 0.5;
  return (
    <div className="flex items-center gap-0.5">
      {Array.from({ length: 5 }, (_, i) => {
        const isFull = i < full;
        const isHalf = i === full && hasHalf;
        return (
          <div key={i} className="relative w-4 h-4">
            <Star size={16} className="absolute inset-0 text-slate-700" />
            {(isFull || isHalf) && (
              <div className="absolute inset-0 overflow-hidden" style={{ width: isHalf ? '50%' : '100%' }}>
                <Star size={16} className="text-amber-400 fill-amber-400" />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

const Row: React.FC<{
  icon: React.ReactNode;
  title: string;
  hint: string;
  value: number;
  labelMap: Record<string, string>;
  onChange: (v: number) => void;
}> = ({ icon, title, hint, value, labelMap, onChange }) => (
  <div className="rounded-xl border border-slate-800 bg-slate-950/60 p-4">
    <div className="flex items-center justify-between mb-2">
      <div className="flex items-center gap-2">
        <span className="text-amber-400">{icon}</span>
        <span className="text-sm font-black uppercase tracking-widest">{title}</span>
      </div>
      <div className="flex items-center gap-2">
        <Stars value={value} />
        <span className="text-sm font-black text-amber-300 tabular-nums w-10 text-right">{value.toFixed(1)}</span>
      </div>
    </div>
    <input
      type="range"
      min={0.5}
      max={5}
      step={0.5}
      value={value}
      onChange={(e) => onChange(parseFloat(e.target.value))}
      className="w-full accent-amber-400"
    />
    <div className="flex items-baseline justify-between mt-1">
      <p className="text-xs text-slate-400">{labelMap[fmtKey(value)] ?? '—'}</p>
      <p className="text-[10px] uppercase tracking-widest text-slate-600">{hint}</p>
    </div>
  </div>
);

export const TravelLogisticsCard: React.FC<Props> = ({ tycoon }) => {
  const defaults = TIER_DEFAULTS[tycoon.tier];
  const [hotel, setHotel] = useState<number>(defaults.hotel);
  const [flight, setFlight] = useState<number>(defaults.flight);
  const [bus, setBus] = useState<number>(defaults.bus);

  const euroleagueWarning = useMemo(() => hotel < 4, [hotel]);

  return (
    <div className="rounded-2xl border border-slate-800 bg-slate-900/70 p-5">
      <h2 className="font-black uppercase tracking-widest mb-4 text-sm flex items-center gap-2">
        <Plane size={14} className="text-amber-400" /> Travel & Logistics
        <HelpIconPopover
          title="Travel Preferences"
          body={
            <>
              <p>Pick the standard your club travels at. Each axis runs from <strong>0.5★</strong> (rock-bottom) to <strong>5★</strong> (luxury) in 0.5 steps.</p>
              <p><strong>Hotel:</strong> ★★★★ is the EuroLeague Bylaws floor for visiting teams (single rooms, extra-long beds, recovery facilities). Liga Endesa follows the same protocol.</p>
              <p><strong>Flight:</strong> Most Liga-only trips run on premium coaches; EuroLeague away games typically need charter jets to keep the schedule recoverable.</p>
              <p><strong>Bus:</strong> Domestic short hops. Premium tiers reduce travel-day fatigue.</p>
              <p className="text-amber-300">Recovery impact + premium pricing on the ledger ship in a follow-up. Today these sliders are a preview — costs and fatigue still run on the flat model.</p>
            </>
          }
        />
      </h2>
      <div className="space-y-3">
        <Row
          icon={<Hotel size={14} />}
          title="Hotel"
          hint="Per-night class"
          value={hotel}
          labelMap={HOTEL_LABELS}
          onChange={setHotel}
        />
        <Row
          icon={<Plane size={14} />}
          title="Flight"
          hint="Long-haul / Euroleague"
          value={flight}
          labelMap={FLIGHT_LABELS}
          onChange={setFlight}
        />
        <Row
          icon={<Bus size={14} />}
          title="Bus"
          hint="Domestic short trips"
          value={bus}
          labelMap={BUS_LABELS}
          onChange={setBus}
        />
      </div>
      {euroleagueWarning && (
        <div className="mt-3 rounded-lg border border-rose-500/30 bg-rose-500/10 px-3 py-2 text-xs text-rose-200">
          EuroLeague Bylaws require visiting-team hotels at ★★★★ minimum. Below that the league can fine the club.
        </div>
      )}
      <p className="mt-3 text-[10px] uppercase tracking-widest text-slate-600">
        Preview · recovery + cost impact lands with the travel economy update
      </p>
    </div>
  );
};

