export type SponsorshipSlot =
  | 'kit' | 'sleeve' | 'back' | 'shorts'
  | 'training' | 'court'
  | 'stadium' | 'practice';

export const ALL_SLOTS: SponsorshipSlot[] = [
  'kit', 'sleeve', 'back', 'shorts',
  'training', 'court',
  'stadium', 'practice',
];

export const CASH_SLOTS: SponsorshipSlot[] = ['kit', 'sleeve', 'back', 'shorts', 'training', 'court'];

export type TycoonTier = 'S' | 'A' | 'B' | 'C' | 'D';

export type SponsorIndustry =
  | 'airline' | 'tech' | 'fashion' | 'bank' | 'auto' | 'telecom'
  | 'beer' | 'water' | 'energy_drink' | 'gambling' | 'sportswashing'
  | 'generic';

export interface Sponsorship {
  sponsor: string;
  industry?: SponsorIndustry;
