export function getTierForClub(clubName: string): TycoonTier {
  if (!clubName) return 'D';
  if (SPAIN_CLUB_TIERS[clubName]) return SPAIN_CLUB_TIERS[clubName];
  const firstTwo = clubName.split(' ').slice(0, 2).join(' ');
  if (SPAIN_CLUB_TIERS[firstTwo]) return SPAIN_CLUB_TIERS[firstTwo];
  const firstWord = clubName.split(' ')[0];
  if (SPAIN_CLUB_TIERS[firstWord]) return SPAIN_CLUB_TIERS[firstWord];
  return 'D';
}

export function getCityPrestige(clubName: string, tier: TycoonTier): number {
  if (clubName) {
    if (SPAIN_CITY_PRESTIGE[clubName] !== undefined) return SPAIN_CITY_PRESTIGE[clubName];
    const firstTwo = clubName.split(' ').slice(0, 2).join(' ');
    if (SPAIN_CITY_PRESTIGE[firstTwo] !== undefined) return SPAIN_CITY_PRESTIGE[firstTwo];
    const firstWord = clubName.split(' ')[0];
    if (SPAIN_CITY_PRESTIGE[firstWord] !== undefined) return SPAIN_CITY_PRESTIGE[firstWord];
  }
  return TIER_PRESTIGE_DEFAULT[tier];
}

import type { Sponsorship, SponsorshipSlot, TycoonState, TycoonTier } from '../../types/tycoon';
import { ALL_SLOTS } from '../../types/tycoon';
import { TIER_BASE, SPAIN_INITIAL_SPONSORS } from './specs/spain';

export interface SuccessHistory {
  recentEndesaPositions: number[];
  recentEuroleagueStages: Array<'final-four' | 'qf' | 'group' | 'none'>;
}

export interface SponsorshipOffer {
  slot: SponsorshipSlot;
  sponsor: string;
  valuePerYear: number;
  signingBonus: number;
  years: number;
}

const PRESTIGE_BUMP: Record<TycoonTier, number> = { S: 0.5, A: 0.3, B: 0.1, C: 0.0, D: -0.1 };

function recentSuccessBonus(h: SuccessHistory): number {
  let b = 0;
  for (const pos of h.recentEndesaPositions ?? []) {
    if (pos >= 1 && pos <= 4) b += 0.05;
  }
  for (const st of h.recentEuroleagueStages ?? []) {
    if (st === 'final-four') b += 0.10;
    else if (st === 'qf') b += 0.05;
  }
  return Math.min(0.45, b);
}

function pickSponsorName(tier: TycoonTier, slot: SponsorshipSlot, existing?: string | null): string {
  const pool = SPAIN_INITIAL_SPONSORS[tier]?.[slot] ?? ['Default Sponsor'];
  const filtered = existing ? pool.filter(n => n !== existing) : pool;
  if (filtered.length === 0) return pool[0];
  return filtered[Math.floor(Math.random() * filtered.length)];
}

function cityScale(state: TycoonState): number {
  // cityPrestige is 0..1; map to a multiplier 0.5..1.4
  const p = state.cityPrestige ?? 0.5;
  return 0.5 + p * 0.9;
}

export function getMarketOffer(
  state: TycoonState,
  slot: SponsorshipSlot,
  history: SuccessHistory,
): SponsorshipOffer {
  const tb = TIER_BASE[state.tier];
  const existing = state.sponsorships[slot];
  const successBonus = recentSuccessBonus(history);
  const loyaltyBonus = existing ? 0.10 : 0;
  const penalty = state.nextRenewalPenaltyFactor ?? 1.0;
  const noise = 0.95 + Math.random() * 0.10;

  const floor = tb.sponsorshipFloor[slot] ?? 0;
  const value = Math.round(
    floor *
    cityScale(state) *
    (1 + successBonus) *
    (1 + PRESTIGE_BUMP[state.tier]) *
    (1 + loyaltyBonus) *
    penalty *
    noise
  );

  const signingBonus = Math.round(value * (0.5 + Math.random() * 1.0));

  return {
    slot,
    sponsor: existing?.sponsor ?? pickSponsorName(state.tier, slot, null),
    valuePerYear: value,
    signingBonus,
    years: 3 + Math.floor(Math.random() * 2),
  };
}

export function applyRenewal(state: TycoonState, slot: SponsorshipSlot, offer: SponsorshipOffer, currentYear: number): void {
  state.sponsorships[slot] = {
    sponsor: offer.sponsor,
    valuePerYear: offer.valuePerYear,
    signingBonus: offer.signingBonus,
    yearsRemaining: offer.years,
    signedYear: currentYear,
  };
  delete state.nextRenewalPenaltyFactor;
}

export function applyDecline(state: TycoonState, slot: SponsorshipSlot): void {
  state.sponsorships[slot] = null;
}

export function dekrementSponsorshipYears(state: TycoonState): void {
  ALL_SLOTS.forEach(slot => {
    const s = state.sponsorships[slot];
    if (!s) return;
    s.yearsRemaining -= 1;
    if (s.yearsRemaining <= 0) {
      state.sponsorships[slot] = null;
    }
  });
}

export function seedInitialSponsorships(
  tier: TycoonTier,
  currentYear: number,
  cityPrestige?: number,
): TycoonState['sponsorships'] {
  const tb = TIER_BASE[tier];
  const scale = 0.5 + (cityPrestige ?? 0.5) * 0.9;
  const make = (slot: SponsorshipSlot): Sponsorship => {
    const floor = tb.sponsorshipFloor[slot] ?? 0;
    const value = Math.round(floor * scale * (0.9 + Math.random() * 0.3));
    return {
      sponsor: pickSponsorName(tier, slot, null),
      valuePerYear: value,
      signingBonus: Math.round(value * (0.4 + Math.random() * 0.6)),
      yearsRemaining: 1 + Math.floor(Math.random() * 4),
      signedYear: currentYear - 1,
    };
  };
  const out = {} as Record<SponsorshipSlot, Sponsorship | null>;
  ALL_SLOTS.forEach(s => { out[s] = make(s); });
  return out;
}

export function hasExpiredSlot(state: TycoonState): boolean {
  return ALL_SLOTS.some(s => state.sponsorships[s] === null);
}

import type { NBATeam, NonNBATeam } from '../../types';
import type { Sponsorship, SponsorshipSlot, TycoonState } from '../../types/tycoon';
import { ALL_SLOTS } from '../../types/tycoon';
import { TIER_BASE, getTierForClub, getCityPrestige, SPAIN_INITIAL_SPONSORS } from './specs/spain';
import { seedInitialSponsorships } from './sponsorshipEngine';

type TycoonHost = NBATeam | NonNBATeam;

function makeFallback(tier: TycoonState['tier'], slot: SponsorshipSlot, cityPrestige: number, currentYear: number): Sponsorship {
  const floor = TIER_BASE[tier].sponsorshipFloor[slot] ?? 0;
  const scale = 0.5 + cityPrestige * 0.9;
  const pool = SPAIN_INITIAL_SPONSORS[tier]?.[slot] ?? ['Default Sponsor'];
  const value = Math.round(floor * scale * 0.6);
  return {
    sponsor: pool[Math.floor(Math.random() * pool.length)],
    valuePerYear: value,
    signingBonus: Math.round(value * 0.3),
    yearsRemaining: 1 + Math.floor(Math.random() * 2),
    signedYear: currentYear - 1,
  };
}

function getClubName(team: TycoonHost): string {
  return (team as NBATeam).name ?? (team as NonNBATeam).name ?? '';
}
function getClubRegion(team: TycoonHost): string {
  return (team as NBATeam).region ?? (team as NonNBATeam).region ?? '';
}

export function migrateTeamTycoon(team: TycoonHost, currentYear: number): void {
  const name = getClubName(team);
  const region = getClubRegion(team);
  const existing = (team as any).tycoon as TycoonState | undefined;

  if (existing) {
    upgradeExistingTycoon(existing, name, region, currentYear);
    return;
  }

  const tier = getTierForClub(name || region);
  const tb = TIER_BASE[tier];
  const cityPrestige = getCityPrestige(name || region, tier);

  (team as any).tycoon = {
    tier,
    cityPrestige,
    ticketPriceMultiplier: 1.0,
    sponsorships: seedInitialSponsorships(tier, currentYear, cityPrestige),
    facilities: {
      stadium: { level: 1, capacity: tb.stadiumCapacity },
      trainingCenter: { level: 1 },
      academy: { level: 1 },
    },
    ledgerHistory: [],
    cashOnHand: tb.startingCash,
    boardConfidence: 60,
    ffpRollingDeficit: 0,
  } as TycoonState;
}

/** Upgrade an existing TycoonState in-place to the v2 schema (8 slots, prestige, ticketMult). */
function upgradeExistingTycoon(t: TycoonState, name: string, region: string, currentYear: number): void {
  // 1. Re-resolve tier if a name-lookup now matches. Avoids "Real Madrid stuck on Tier D" from earlier seeds.
  const resolvedTier = getTierForClub(name || region);
  if (resolvedTier !== 'D' && t.tier !== resolvedTier) {
    t.tier = resolvedTier;
  }

  // 2. Backfill cityPrestige + ticketPriceMultiplier.
  if (t.cityPrestige === undefined) t.cityPrestige = getCityPrestige(name || region, t.tier);
  if (t.ticketPriceMultiplier === undefined) t.ticketPriceMultiplier = 1.0;

  // 3. Extend sponsorships from 3 slots to 8 (fallback seeds for new slots).
  const existing = t.sponsorships as Record<string, Sponsorship | null>;
  const upgraded = {} as Record<SponsorshipSlot, Sponsorship | null>;
  for (const slot of ALL_SLOTS) {
    if (slot in existing) {
      upgraded[slot] = existing[slot];
    } else {
      upgraded[slot] = makeFallback(t.tier, slot, t.cityPrestige ?? 0.5, currentYear);
    }
  }
  t.sponsorships = upgraded;
}

export function migrateAllEuroTeams(state: {
  teams: NBATeam[];
  nonNBATeams?: NonNBATeam[];
  leagueStats: { year: number; uiMode?: string | null };
}): number {
  if (state.leagueStats?.uiMode !== 'euro_isolated') return 0;
  let migrated = 0;
  const clubs: TycoonHost[] = [...state.teams, ...(state.nonNBATeams ?? [])];
  for (const team of clubs) {
    migrateTeamTycoon(team, state.leagueStats.year);
    migrated++;
  }
  return migrated;
}

