import React from 'react';
import { Handshake, Ticket, Dumbbell } from 'lucide-react';
import type { TycoonState, SponsorshipSlot } from '../../types/tycoon';
import { formatCurrencyWithCode } from '../../utils/helpers';
import { HelpIconPopover } from './HelpIconPopover';
import { TIER_BASE } from '../../services/tycoon/specs/spain';

interface Props {
  tycoon: TycoonState;
  currency: string;
  onNegotiate: (slot: SponsorshipSlot) => void;
  onTicketMultChange?: (mult: number) => void;
}

const SLOT_LABELS: Record<SponsorshipSlot, string> = {
  kit: 'Kit',
  sleeve: 'Sleeve',
  back: 'Back',
  shorts: 'Shorts',
  training: 'Training Kit',
  court: 'Court Logo',
  stadium: 'Stadium Naming',
  practice: 'Practice Facility',
};

const CASH_SLOTS: SponsorshipSlot[] = ['kit', 'sleeve', 'back', 'shorts', 'training', 'court'];

const SlotTile: React.FC<{
  slot: SponsorshipSlot;
  deal: ReturnType<() => TycoonState['sponsorships'][SponsorshipSlot]>;
  fmt: (v: number) => string;
  onNegotiate: (slot: SponsorshipSlot) => void;
  extraNote?: string;
}> = ({ slot, deal, fmt, onNegotiate, extraNote }) => {
  const expired = deal === null;
  return (
    <div className={`rounded-xl border p-3 ${expired ? 'border-amber-500/50 bg-amber-500/5' : 'border-slate-700 bg-slate-900/40'}`}>
      <div className="flex justify-between items-start mb-1">
        <span className="text-xs font-semibold text-slate-400">{SLOT_LABELS[slot]}</span>
        <button
          onClick={() => onNegotiate(slot)}
          className={`text-xs font-semibold px-2 py-0.5 rounded ${expired ? 'bg-amber-500 text-slate-950' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}
        >
          {expired ? 'Renew →' : 'Negotiate'}
        </button>
      </div>
      {deal ? (
        <>
          <p className="text-sm font-bold text-white">{deal.sponsor}</p>
          <p className="text-xs text-slate-400">
            {fmt(deal.valuePerYear)}/yr · <span className={deal.yearsRemaining === 1 ? 'text-amber-300' : 'text-slate-400'}>{deal.yearsRemaining}y left</span>
          </p>
        </>
      ) : (
        <>
          <p className="text-sm font-bold text-amber-300">Default Fallback</p>
          <p className="text-xs text-slate-500">No active deal — negotiate a new sponsor</p>
        </>
      )}
      {extraNote && <p className="mt-2 text-xs text-slate-500">{extraNote}</p>}
    </div>
  );
};

export const SponsorshipCard: React.FC<Props> = ({ tycoon, currency, onNegotiate, onTicketMultChange }) => {
  const fmt = (v: number) => formatCurrencyWithCode(v, currency, false);
  const tb = TIER_BASE[tycoon.tier];
  const ticketMult = tycoon.ticketPriceMultiplier ?? 1.0;
  const ticketPrice = Math.round(tb.ticketPrice * ticketMult);

  // Crowd-mood label based on multiplier (no raw numbers).
  let crowdNote = 'Standard pricing';
  if (ticketMult >= 1.6) crowdNote = 'Premium pricing — empty seats likely';
  else if (ticketMult >= 1.3) crowdNote = 'High pricing — pressure on attendance';
  else if (ticketMult >= 1.1) crowdNote = 'Slightly above market';
  else if (ticketMult <= 0.7) crowdNote = 'Bargain pricing — packed crowds, less revenue per seat';
  else if (ticketMult <= 0.9) crowdNote = 'Below market — friendly to fans';

  return (
    <div className="rounded-2xl border border-slate-800 bg-slate-900/70 p-5">
      <h2 className="font-bold mb-4 text-base flex items-center gap-2 text-slate-100">
        <Handshake size={16} className="text-amber-400" /> Sponsorship Deals
        <HelpIconPopover
          title="Sponsorship Slots"
          body={
            <>
