const applyTycoonMutation = (teamId: number, mutator: (team: any) => void) => {
  setState(prev => {
    const nbaTeam = prev.teams.find((t: any) => (t.id ?? t.tid) === teamId);
    if (nbaTeam) {
      mutator(nbaTeam);
      return { ...prev, teams: [...prev.teams] };
