    const nonTeam = nonNBA.find((t: any) => (t.id ?? t.tid) === teamId);
    if (nonTeam) {
      mutator(nonTeam);
      return { ...prev, nonNBATeams: [...nonNBA] } as any;
    }
    return prev;
  });
};

