export const SponsorshipCard: React.FC<Props> = ({ tycoon, currency, onNegotiate, onTicketMultChange }) => {
  const fmt = (v: number) => formatCurrencyWithCode(v, currency, false);
  const tb = TIER_BASE[tycoon.tier];
  const ticketMult = tycoon.ticketPriceMultiplier ?? 1.0;
  const ticketPrice = Math.round(tb.ticketPrice * ticketMult);

  // Mirror the budgetEngine attendance math (kept in sync — see ticketPrice elasticity there).
  const capacity = tycoon.facilities.stadium.capacity;
  const baseFloor: Record<TycoonState['tier'], number> = { S: 0.85, A: 0.75, B: 0.65, C: 0.55, D: 0.45 };
  const stadiumDeal = tycoon.sponsorships.stadium;
  const stadiumFloor = tb.sponsorshipFloor.stadium || 1;
  const stadiumBoost = stadiumDeal
    ? Math.min(0.10, Math.max(0, (stadiumDeal.valuePerYear / stadiumFloor - 1) * 0.05))
    : 0;
  const elasticityPenalty = ticketMult > 1.0 ? Math.min(0.20, (ticketMult - 1.0) * 0.15) : 0;
  const effAttendance = Math.max(0.2, Math.min(0.99, baseFloor[tycoon.tier] + stadiumBoost - elasticityPenalty));
  const projectedAttendees = Math.round(capacity * effAttendance);
  const projectedMatchday = projectedAttendees * ticketPrice * 30;

  // Crowd-mood label (no raw numbers) — combines pricing pressure + attendance level.
  let crowdNote = 'Standard pricing';
  if (ticketMult >= 1.6) crowdNote = 'Premium pricing — empty seats likely';
  else if (ticketMult >= 1.3) crowdNote = 'High pricing — pressure on attendance';
  else if (ticketMult >= 1.1) crowdNote = 'Slightly above market';
  else if (ticketMult <= 0.7) crowdNote = 'Bargain pricing — packed crowds, less revenue per seat';
  else if (ticketMult <= 0.9) crowdNote = 'Below market — friendly to fans';

  let crowdEnergyLabel = 'Solid crowd';
  if (effAttendance >= 0.95) crowdEnergyLabel = 'Sold out — every home game';
  else if (effAttendance >= 0.85) crowdEnergyLabel = 'Packed house';
  else if (effAttendance >= 0.70) crowdEnergyLabel = 'Solid crowd';
  else if (effAttendance >= 0.55) crowdEnergyLabel = 'Half-empty rows';
  else crowdEnergyLabel = 'Sparse turnout';

