import {
  getMarketOffer,
  applyRenewal,
  applyDecline,
  dekrementSponsorshipYears,
  seedInitialSponsorships,
  hasExpiredSlot,
} from '../src/services/tycoon/sponsorshipEngine';
import { ALL_SLOTS } from '../src/types/tycoon';
import type { Sponsorship, SponsorshipSlot, TycoonState, TycoonTier } from '../src/types/tycoon';

function makeTycoon(tier: TycoonTier, prestige = 1.0): TycoonState {
  const sponsorships = {} as Record<SponsorshipSlot, Sponsorship | null>;
  for (const slot of ALL_SLOTS) {
    sponsorships[slot] = { sponsor: `X-${slot}`, valuePerYear: 100_000, yearsRemaining: 3, signedYear: 2024 };
  }
  return {
    tier,
    cityPrestige: prestige,
    ticketPriceMultiplier: 1.0,
    sponsorships,
    facilities: { stadium: { level: 1, capacity: 15000 }, trainingCenter: { level: 1 }, academy: { level: 1 } },
    ledgerHistory: [],
    cashOnHand: 10_000_000,
    boardConfidence: 60,
    ffpRollingDeficit: 0,
  };
}

const assert = (c: boolean, m: string) => {
  if (!c) { console.error('FAIL:', m); process.exit(1); }
};

// S-tier with full prestige + success — kit offer should be in the millions
const sTycoon = makeTycoon('S', 1.0);
const offerS = getMarketOffer(sTycoon, 'kit', {
  recentEndesaPositions: [1, 1, 2],
  recentEuroleagueStages: ['final-four', 'qf', 'final-four'],
});
console.log('S-Tier Kit Offer:', offerS);
assert(offerS.valuePerYear > 3_000_000, `S-Tier with success bonus > 3M (got ${offerS.valuePerYear})`);
assert(offerS.years >= 3 && offerS.years <= 4, `Years 3–4 (got ${offerS.years})`);
assert(offerS.signingBonus > 0, `Signing bonus present (got ${offerS.signingBonus})`);

// D-tier with low prestige + no success — kit offer should be small
const dTycoon = makeTycoon('D', 0.3);
const offerD = getMarketOffer(dTycoon, 'kit', {
  recentEndesaPositions: [16, 18, 17],
  recentEuroleagueStages: ['none', 'none', 'none'],
});
console.log('D-Tier Kit Offer:', offerD);
assert(offerD.valuePerYear < 200_000, `D-Tier with no success small (got ${offerD.valuePerYear})`);

// S-tier with low prestige (hypothetical small-city Tier S) — should scale down
const sLowPrestige = makeTycoon('S', 0.3);
const offerSLow = getMarketOffer(sLowPrestige, 'kit', {
  recentEndesaPositions: [],
  recentEuroleagueStages: [],
});
console.log('S-Tier Low-Prestige Kit Offer:', offerSLow);
assert(offerSLow.valuePerYear < offerS.valuePerYear, 'low cityPrestige scales S-Tier kit down');

// All 8 slots have an offer path
for (const slot of ALL_SLOTS) {
  const o = getMarketOffer(sTycoon, slot, { recentEndesaPositions: [], recentEuroleagueStages: [] });
  assert(o.valuePerYear > 0, `S-Tier ${slot} offer > 0 (got ${o.valuePerYear})`);
}

// Accept (signing-bonus also pumps cash)
const cashBefore = sTycoon.cashOnHand;
applyRenewal(sTycoon, 'kit', offerS, 2026);
assert(sTycoon.sponsorships.kit?.valuePerYear === offerS.valuePerYear, 'kit replaced with new offer');
assert(sTycoon.sponsorships.kit?.yearsRemaining === offerS.years, 'kit years set');
assert(sTycoon.sponsorships.kit?.signedYear === 2026, 'signedYear set');
assert(sTycoon.cashOnHand === cashBefore + offerS.signingBonus, 'cashOnHand += signingBonus');

// Decline
applyDecline(sTycoon, 'sleeve');
assert(sTycoon.sponsorships.sleeve === null, 'sleeve cleared on decline');
assert(hasExpiredSlot(sTycoon), 'hasExpiredSlot true after decline');

// Decrement loops over 8 slots
const sTycoon2 = makeTycoon('S');
sTycoon2.sponsorships.kit!.yearsRemaining = 1;
sTycoon2.sponsorships.practice!.yearsRemaining = 1;
dekrementSponsorshipYears(sTycoon2);
assert(sTycoon2.sponsorships.kit === null, 'kit-with-1y becomes null after decrement+expire');
assert(sTycoon2.sponsorships.practice === null, 'practice-with-1y becomes null after decrement+expire');
assert(sTycoon2.sponsorships.stadium?.yearsRemaining === 2, `stadium 3→2 (got ${sTycoon2.sponsorships.stadium?.yearsRemaining})`);

// Seed produces 8 slots
const seeded = seedInitialSponsorships('A', 2026, 0.8);
for (const slot of ALL_SLOTS) {
  assert(seeded[slot] !== null, `A-tier seed has ${slot}`);
}
assert(seeded.kit!.signingBonus !== undefined && seeded.kit!.signingBonus! > 0, 'seed includes signing bonus');
assert(seeded.kit!.yearsRemaining >= 1 && seeded.kit!.yearsRemaining <= 4, 'kit years 1–4');

console.log('\n✓ All sponsor assertions passed');

