import { getTeamFullName } from '../../../utils/teamNames';
import { formatCurrencyWithCode } from '../../../utils/helpers';
import { SponsorshipCard } from '../../tycoon/SponsorshipCard';
import { SponsorshipNegotiationModal } from '../../tycoon/SponsorshipNegotiationModal';
import { TravelLogisticsCard } from '../../tycoon/TravelLogisticsCard';
import { computeAnnualBudget } from '../../../services/tycoon/budgetEngine';
import { getCityPrestige } from '../../../services/tycoon/specs/spain';
import type { SponsorshipSlot } from '../../../types/tycoon';

export const FrontOfficeView: React.FC = () => {
  const { state, applyTycoonMutation, setCurrentView } = useGame() as any;
  const currency = state.leagueStats?.currency ?? 'EUR';
  const userTeamId = state.userTeamId;
  const selectedTeam = resolveAnyTeam(userTeamId, state.teams, state.nonNBATeams ?? []);
  const tycoon = (selectedTeam as any)?.tycoon;
  const currentYear = state.leagueStats?.year ?? new Date().getFullYear();

  const [sponsorModal, setSponsorModal] = useState<{ open: boolean; slot: SponsorshipSlot }>({ open: false, slot: 'kit' });

  const handleTicketMultChange = (mult: number) => {
    applyTycoonMutation(userTeamId, (t: any) => {
      if (!t.tycoon) return;
      t.tycoon.ticketPriceMultiplier = Math.max(0.5, Math.min(2.0, mult));
    });
  };

  // Compute average opponent prestige + marquee opponent list (excl. self).
  const { avgOpponentPrestige, marqueeOpponents } = useMemo(() => {
    if (!selectedTeam) return { avgOpponentPrestige: 0.5, marqueeOpponents: [] as string[] };
    const opponents: any[] = [...(state.teams ?? []), ...(state.nonNBATeams ?? [])]
      .filter((t: any) => (t.id ?? t.tid) !== userTeamId && t.tycoon);
    if (opponents.length === 0) return { avgOpponentPrestige: 0.5, marqueeOpponents: [] };
    const prestigeOf = (t: any): number =>
      t.tycoon?.cityPrestige ?? getCityPrestige(t.name ?? t.region ?? '', t.tycoon?.tier ?? 'D');
    const total = opponents.reduce((sum, t) => sum + prestigeOf(t), 0);
    const avg = total / opponents.length;
    const marquee = opponents
      .filter(t => prestigeOf(t) >= 0.7)
      .map(t => (t.region && !String(t.name).includes(t.region)) ? `${t.region} ${t.name}` : t.name)
      .slice(0, 5);
    return { avgOpponentPrestige: avg, marqueeOpponents: marquee };
  }, [selectedTeam, state.teams, state.nonNBATeams, userTeamId]);

  // Live ledger projection — reflects slider/sponsor changes immediately.
  const ledger = useMemo(() => {
    if (!selectedTeam || !tycoon) return null;
    return computeAnnualBudget(selectedTeam as any, {
      year: currentYear,
      endesaFinishPosition: (selectedTeam as any).lastEndesaFinish ?? 9,
      euroleagueStage: (selectedTeam as any).lastEuroleagueStage ?? 'none',
      euroleagueAwayGames: (selectedTeam as any).lastEuroAwayGames ?? 0,
      endesaPrizeEUR: 0,
      euroleaguePrizeEUR: 0,
      avgOpponentPrestige,
    }, state.players);
  }, [selectedTeam, tycoon, currentYear, avgOpponentPrestige, state.players]);

  if (!selectedTeam || !tycoon) {
    return (
      <div className="h-full overflow-y-auto p-8 bg-slate-950 text-white">
        <button onClick={() => setCurrentView('Schedule')} className="flex items-center gap-2 text-slate-400 hover:text-white text-sm mb-6">
          <ArrowLeft size={16} /> Back
        </button>
        <p className="text-slate-400">Front office is only available in club-management mode. Try reloading the save.</p>
      </div>
    );
  }

  const internationalAway = (selectedTeam as any).lastEuroAwayGames ?? 0;
  const fmt = (v: number) => formatCurrencyWithCode(v, currency, false);

  return (
    <div className="h-full overflow-y-auto bg-slate-950 text-white">
      <div className="max-w-6xl mx-auto p-4 md:p-8 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <div className="text-[10px] font-bold uppercase tracking-[0.35em] text-amber-300 flex items-center gap-2">
              <Briefcase size={12} /> Front Office · Tier {tycoon.tier}
            </div>
            <h1 className="text-3xl font-black tracking-tight mt-1">{getTeamFullName(selectedTeam as any)}</h1>
            <p className="text-sm text-slate-400 mt-1">Manage sponsorship deals, ticket pricing, and travel preferences.</p>
          </div>
          <button
            onClick={() => setCurrentView('Team Finances')}
            className="text-xs font-semibold text-slate-400 hover:text-white"
          >
            View read-only ledger →
          </button>
        </div>

        {ledger && (
          <AnnualProjectionCard ledger={ledger} fmt={fmt} cashOnHand={tycoon.cashOnHand ?? 0} currentYear={currentYear} />
        )}

        <div className="grid lg:grid-cols-2 gap-6">
          <SponsorshipCard
            tycoon={tycoon}
            currency={currency}
            onNegotiate={(slot) => setSponsorModal({ open: true, slot })}
            onTicketMultChange={handleTicketMultChange}
            avgOpponentPrestige={avgOpponentPrestige}
            marqueeOpponents={marqueeOpponents}
          />
          <TravelLogisticsCard
            tycoon={tycoon}
            currency={currency}
            domesticAwayGames={17}
            internationalAwayGames={internationalAway}
          />
        </div>
      </div>

      <SponsorshipNegotiationModal
        open={sponsorModal.open}
        onClose={() => setSponsorModal({ open: false, slot: 'kit' })}
        initialSlot={sponsorModal.slot}
      />
    </div>
  );
};

const Line: React.FC<{ label: string; value: number; fmt: (v: number) => string; sign?: 'in' | 'out'; emphasis?: boolean }> =
  ({ label, value, fmt, sign = 'in', emphasis }) => (
  <div className={`flex justify-between items-baseline ${emphasis ? 'pt-2 border-t border-slate-800' : ''}`}>
    <span className={`text-sm ${emphasis ? 'font-bold text-slate-200' : 'text-slate-400'}`}>{label}</span>
    <span className={`tabular-nums ${emphasis ? 'text-base font-bold' : 'text-sm font-semibold'} ${
      sign === 'out' ? 'text-rose-300' : 'text-emerald-300'
    }`}>
      {sign === 'out' ? '−' : ''}{fmt(Math.abs(value))}
    </span>
  </div>
);

const AnnualProjectionCard: React.FC<{
  ledger: ReturnType<typeof computeAnnualBudget>;
  fmt: (v: number) => string;
  cashOnHand: number;
  currentYear: number;
}> = ({ ledger, fmt, cashOnHand, currentYear }) => {
  const totalRevenue = ledger.revenue.matchday + ledger.revenue.sponsorship + ledger.revenue.tv + ledger.revenue.prize;
  const totalExpenses = ledger.expenses.wages + ledger.expenses.staff + ledger.expenses.facility + ledger.expenses.travel + ledger.expenses.financeCosts;
  const profit = totalRevenue - totalExpenses;
  const cashEnd = cashOnHand + profit;
  const profitable = profit >= 0;

  return (
    <div className="rounded-2xl border border-slate-800 bg-slate-900/70 p-5">
      <div className="flex items-center justify-between mb-4">
        <h2 className="font-bold text-base flex items-center gap-2 text-slate-100">
          {profitable ? <TrendingUp size={16} className="text-emerald-400" /> : <TrendingDown size={16} className="text-rose-400" />}
          Annual Projection · {currentYear}
        </h2>
        <span className="text-xs text-slate-500">Live preview — reflects your slider + sponsorship changes</span>
      </div>

      <div className="grid md:grid-cols-2 gap-6">
        <div>
          <p className="text-xs font-semibold uppercase tracking-wider text-emerald-300 mb-2">Cash In</p>
          <div className="space-y-1.5">
            <Line label="Matchday" value={ledger.revenue.matchday} fmt={fmt} />
            <Line label="Sponsorships (8 slots)" value={ledger.revenue.sponsorship} fmt={fmt} />
            <Line label="TV Rights" value={ledger.revenue.tv} fmt={fmt} />
            {ledger.revenue.prize > 0 && <Line label="Prize Money" value={ledger.revenue.prize} fmt={fmt} />}
            <Line label="Total Revenue" value={totalRevenue} fmt={fmt} emphasis />
          </div>
        </div>

        <div>
          <p className="text-xs font-semibold uppercase tracking-wider text-rose-300 mb-2">Cash Out</p>
          <div className="space-y-1.5">
            <Line label="Wages" value={ledger.expenses.wages} fmt={fmt} sign="out" />
            <Line label="Staff (≈10% of wages)" value={ledger.expenses.staff} fmt={fmt} sign="out" />
            <Line label="Facility Operations" value={ledger.expenses.facility} fmt={fmt} sign="out" />
            <Line label="Travel" value={ledger.expenses.travel} fmt={fmt} sign="out" />
            {ledger.expenses.financeCosts > 0 && <Line label="Finance Costs (debt)" value={ledger.expenses.financeCosts} fmt={fmt} sign="out" />}
            <Line label="Total Expenses" value={totalExpenses} fmt={fmt} sign="out" emphasis />
          </div>
        </div>
      </div>

      <div className="mt-5 grid grid-cols-2 gap-4">
        <div className="rounded-xl border border-slate-700 bg-slate-950/60 p-3">
          <p className="text-xs text-slate-500">Projected Profit</p>
          <p className={`text-2xl font-black tabular-nums ${profitable ? 'text-emerald-400' : 'text-rose-400'}`}>
            {profitable ? '' : '−'}{fmt(Math.abs(profit))}
          </p>
        </div>
        <div className="rounded-xl border border-slate-700 bg-slate-950/60 p-3">
          <p className="text-xs text-slate-500">Year-End Cash on Hand</p>
          <p className={`text-2xl font-black tabular-nums ${cashEnd >= 0 ? 'text-amber-300' : 'text-rose-400'}`}>
            {cashEnd < 0 ? '−' : ''}{fmt(Math.abs(cashEnd))}
          </p>
        </div>
      </div>
    </div>
  );
};

