if (action.type === 'OFFSEASON_RESET_CHECKLIST') {
  // Called once when offseason starts (or by debug tools to retry a phase).
  setState(prev => ({
    ...prev,
    offseasonChecklist: defaultOffseasonChecklist(prev.leagueStats),
    faTagCounter: undefined,
    pendingOfferDecisions: [],
  }));
  return;
}

// ── Transfer Market actions ───────────────────────────────────────────
if (action.type === 'LIST_PLAYER_FOR_TRANSFER') {
  const { playerId, sellerTid, askingEUR, durationDays } = action.payload as {
    playerId: string; sellerTid: number; askingEUR: number; durationDays?: number;
  };
  setState(prev => {
    // Idempotency: don't double-list the same player.
    const existing = (prev.transferListings ?? []).find(l => l.playerId === playerId && l.status === 'active');
    if (existing) return prev;
    const listing = buildListing({
      playerId, sellerTid, askingEUR, durationDays,
      currentDate: prev.date,
    });
    return { ...prev, transferListings: [...(prev.transferListings ?? []), listing] };
  });
  return;
}

if (action.type === 'CANCEL_TRANSFER_LISTING') {
  const { listingId } = action.payload as { listingId: string };
  setState(prev => {
    const listings = (prev.transferListings ?? []).map(l =>
      l.id === listingId && l.status === 'active' ? { ...l, status: 'cancelled' as const } : l
    );
    // Withdraw all open bids on it.
    const bids = (prev.transferBids ?? []).map(b =>
      b.listingId === listingId && (b.status === 'active' || b.status === 'highest')
        ? { ...b, status: 'withdrawn' as const }
        : b
    );
    return { ...prev, transferListings: listings, transferBids: bids };
  });
  return;
}

if (action.type === 'SUBMIT_TRANSFER_BID') {
  const payload = action.payload as {
    listingId?: string; playerId: string; bidderTid: number; sellerTid: number;
    bidType: TransferBid['bidType']; amountEUR: number; validDays?: number;
  };
  setState(prev => {
    const bid = buildBid({ ...payload, currentDate: prev.date });
    let bids = [...(prev.transferBids ?? []), bid];
    let listings = prev.transferListings ?? [];
    if (payload.listingId) {
      bids = markHighest(bids, payload.listingId);
      listings = syncListingRollups(listings, bids);
    }
    return { ...prev, transferBids: bids, transferListings: listings };
  });
  return;
}

if (action.type === 'REJECT_TRANSFER_BID') {
  const { bidId } = action.payload as { bidId: string };
  setState(prev => {
    const bids = (prev.transferBids ?? []).map(b =>
      b.id === bidId ? { ...b, status: 'rejected' as const } : b
    );
    const target = bids.find(b => b.id === bidId);
    let listings = prev.transferListings ?? [];
    if (target?.listingId) listings = syncListingRollups(listings, bids);
    return { ...prev, transferBids: bids, transferListings: listings };
  });
  return;
}

if (action.type === 'ACCEPT_TRANSFER_BID') {
  const { bidId } = action.payload as { bidId: string };
  setState(prev => {
    const bid = (prev.transferBids ?? []).find(b => b.id === bidId);
    if (!bid) return prev;

    // Execute the move: flip player.tid → bidder, exchange cash on tycoon
    // blocks (where present), close the listing, log activity.
    const players = (prev.players ?? []).map(p =>
      p.internalId === bid.playerId ? { ...p, tid: bid.bidderTid } : p
    );
    const movedPlayer = players.find(p => p.internalId === bid.playerId);

    // Cash exchange — Euro tycoon teams have cashOnHand in EUR.
    const adjustCash = (teamsArr: any[], tid: number, deltaEUR: number) =>
      teamsArr.map(t => {
        const id = t.id ?? t.tid;
        if (id !== tid || !t.tycoon) return t;
        return { ...t, tycoon: { ...t.tycoon, cashOnHand: (t.tycoon.cashOnHand ?? 0) + deltaEUR } };
      });
    const fee = bid.amountEUR;
    let teams = prev.teams ?? [];
    let nonNBA = (prev as any).nonNBATeams ?? [];
    teams = adjustCash(teams, bid.sellerTid, +fee);
    teams = adjustCash(teams, bid.bidderTid, -fee);
    nonNBA = adjustCash(nonNBA, bid.sellerTid, +fee);
    nonNBA = adjustCash(nonNBA, bid.bidderTid, -fee);

    // Close listing + bids
    const listings = (prev.transferListings ?? []).map(l =>
      l.id === bid.listingId ? { ...l, status: 'sold' as const, daysLeft: 0 } : l
    );
    const bids = (prev.transferBids ?? []).map(b => {
      if (b.id === bidId) return { ...b, status: 'accepted' as const };
      if (b.listingId && b.listingId === bid.listingId && b.id !== bidId) {
        return b.status === 'active' || b.status === 'highest' ? { ...b, status: 'rejected' as const } : b;
      }
      return b;
    });

    const activity = [
      ...(prev.transferActivity ?? []),
      {
        id: newId('act'),
        date: toISO(prev.date),
        fromTid: bid.sellerTid,
        toTid: bid.bidderTid,
        playerId: bid.playerId,
        playerName: movedPlayer?.name ?? '—',
        feeEUR: fee,
        bidType: bid.bidType,
      },
    ].slice(-50); // cap log to last 50

    return {
      ...prev,
      players,
      teams,
      nonNBATeams: nonNBA,
      transferListings: listings,
      transferBids: bids,
      transferActivity: activity,
    };
  });
  return;
}

