// Training Camp day-stepper — advance N calendar days, clamped to opening night.
// Today's preseason games (if scheduled) get played; we land on the morning of
// the target date with that day's games unplayed (matches FA "End Day" feel).
const simTrainingCampDays = (days: number) => {
  if (!state.date) return;
  const today = parseGameDate(state.date);
  const target = new Date(today.getTime() + days * 86_400_000);
  const targetISO = toISODateString(target);
  const lsYear = lsYearOf(state);
  const openingISO = toISODateString(
    getOpeningNightDate(lsYear, state.leagueStats as any, state.schedule as any),
  );
  const clampedISO = targetISO > openingISO ? openingISO : targetISO;
  const todayNorm = normalizeDate(state.date);
  if (todayNorm >= clampedISO) return;
  dispatchAction({
    type: 'SIMULATE_TO_DATE',
    payload: { targetDate: clampedISO, stopBefore: true },
  } as any);
};

