input.new_string:
// ─── Training Camp Footer — sticky "CAMP · DAY X/Y · Sim Day" bar ──────────
//
// Renders during the preCamp offseason phase (trainingCamp → opening night).
// Mirrors the FA Tag Footer pattern: Day counter + Sim Day + Sim Week +
// "To Opening Night" escape hatch. Transfer Market typically remains open
// during these days, so the floating control sits *outside* the sidebar so
// the user can sim while browsing the market.

export const OffseasonTrainingCampFooter: React.FC = () => {
  const { state, dispatchAction } = useGame();
  const confirmActionRef = useRef<(() => void) | null>(null);
  const [confirmSpec, setConfirmSpec] = useState<OffseasonConfirmSpec | null>(null);

  if (!state.offseasonChecklist) return null;
  const campStatus = state.offseasonChecklist.trainingCamp;
  if (campStatus !== 'pending' && campStatus !== 'in-progress') return null;
  if (!state.date) return null;
  const os = getOffseasonState(state.date, state.leagueStats as any, state.schedule as any);
  if (os.phase !== 'preCamp') return null;

  // Day counter — Day 1 = camp start, totals = days between camp start and opening night.
  const today = parseGameDate(state.date);
  const campStart = parseGameDate(os.trainingCampStr);
  const openingNight = parseGameDate(os.openingNightStr);
  const MS_PER_DAY = 86_400_000;
  const totalDays = Math.max(1, Math.round((openingNight.getTime() - campStart.getTime()) / MS_PER_DAY));
  const currentDay = Math.min(totalDays, Math.max(1, Math.round((today.getTime() - campStart.getTime()) / MS_PER_DAY) + 1));
  const isLast = currentDay >= totalDays;

  const openConfirm = (spec: OffseasonConfirmSpec, action: () => void) => {
    confirmActionRef.current = action;
    setConfirmSpec(spec);
  };
  const closeConfirm = () => {
    confirmActionRef.current = null;
    setConfirmSpec(null);
  };

  const advanceDays = (days: number) => {
    const target = new Date(today.getTime() + days * MS_PER_DAY);
    const targetISO = toISODateString(target);
    const openingISO = os.openingNightStr;
    const clampedISO = targetISO > openingISO ? openingISO : targetISO;
    const todayNorm = normalizeDate(state.date!);
    if (todayNorm >= clampedISO) return;
    dispatchAction({
      type: 'SIMULATE_TO_DATE',
      payload: { targetDate: clampedISO, stopBefore: true },
    } as any);
  };
  const handleSimDay = () => advanceDays(1);
  const handleSimWeek = () => advanceDays(7);
  const handleToOpeningNight = () => advanceDays(totalDays); // clamp inside advanceDays

  return (
    <div className="fixed bottom-0 left-0 right-0 z-[170] flex items-center justify-center pointer-events-none px-4 pb-3">
      <div className="pointer-events-auto flex items-center gap-3 px-4 py-2 rounded-2xl bg-slate-950/95 border border-amber-500/40 shadow-2xl backdrop-blur-md">
        <div className="flex flex-col leading-none">
          <span className="text-[8px] font-black uppercase tracking-[0.2em] text-amber-300/80">
            Training Camp
          </span>
          <span className="text-sm font-black text-white tabular-nums uppercase tracking-tight">
            Day {currentDay}/{totalDays}
          </span>
        </div>
        <button
          onClick={() => openConfirm(
            {
              eyebrow: 'Offseason Flow',
              title: isLast ? 'Final Camp Day' : 'Advance Camp Day',
              body: isLast
                ? 'This advances onto opening night. Any remaining preseason games get played.'
                : 'This advances one calendar day. Today\'s preseason games (if scheduled) get played and you land on tomorrow morning. Transfer Market stays open.',
              confirmLabel: isLast ? 'To Opening Night' : 'Sim Day',
            },
            handleSimDay,
          )}
          disabled={state.isProcessing}
          title="Advance one calendar day; preseason games today are played."
          className={`flex items-center gap-1.5 px-4 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest transition-colors ${
            state.isProcessing
              ? 'bg-slate-800 text-slate-600 cursor-not-allowed'
              : 'bg-amber-500 hover:bg-amber-400 text-black'
          }`}
        >
          <FastForward size={12} />
          Sim Day
        </button>
        {!isLast && (
          <button
            onClick={() => openConfirm(
              {
                eyebrow: 'Offseason Flow',
                title: 'Sim One Week',
                body: 'This advances up to 7 days, clamped to opening night. All preseason games in that window get played.',
                confirmLabel: 'Sim Week',
              },
              handleSimWeek,
            )}
            disabled={state.isProcessing}
            title="Advance 7 days (or to opening night, whichever is sooner)."
            className={`flex items-center gap-1.5 px-4 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest transition-colors border ${
              state.isProcessing
                ? 'bg-slate-800 text-slate-600 border-slate-700 cursor-not-allowed'
                : 'bg-amber-600/20 hover:bg-amber-500/30 text-amber-200 border-amber-500/40'
            }`}
          >
            <FastForward size={12} />
            Sim Week
          </button>
        )}
        {!isLast && (
          <button
            onClick={() => openConfirm(
              {
                eyebrow: 'Offseason Flow',
                title: 'Skip to Opening Night',
                body: 'This plays through every remaining camp day, settles preseason games, and lands you on opening night morning.',
                confirmLabel: 'To Opening Night',
              },
              handleToOpeningNight,
            )}
            disabled={state.isProcessing}
            title="Skip the rest of training camp. Preseason games are settled automatically."
            className={`flex items-center gap-1.5 px-4 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest transition-colors border ${
              state.isProcessing
                ? 'bg-slate-800 text-slate-600 border-slate-700 cursor-not-allowed'
                : 'bg-emerald-600/20 hover:bg-emerald-500/30 text-emerald-200 border-emerald-500/40'
            }`}
          >
            <Sparkles size={12} />
            Opening Night
          </button>
        )}
      </div>
      {confirmSpec && createPortal(
        <div className="fixed inset-0 z-[171] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/85 backdrop-blur-sm" onClick={closeConfirm} />
          <div className="relative w-full max-w-lg rounded-2xl border border-amber-500/30 bg-slate-950 shadow-2xl overflow-hidden">
            <div className="px-5 py-4 border-b border-white/10 bg-amber-500/[0.06]">
              <p className="text-[10px] font-black uppercase tracking-[0.35em] text-amber-300 mb-2">{confirmSpec.eyebrow}</p>
              <h2 className="text-xl font-black uppercase tracking-tight text-white">{confirmSpec.title}</h2>
            </div>
            <div className="p-5 space-y-4">
              <p className="text-sm text-slate-300 leading-relaxed">
                {confirmSpec.body}
              </p>
              <div className="flex gap-3">
                <button
                  onClick={closeConfirm}
                  className="flex-1 rounded-xl bg-white/5 hover:bg-white/10 text-white font-black uppercase tracking-widest text-xs py-3 transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={() => {
                    const action = confirmActionRef.current;
                    closeConfirm();
                    action?.();
                  }}
                  className="flex-1 rounded-xl bg-amber-500 hover:bg-amber-400 text-black font-black uppercase tracking-widest text-xs py-3 transition-colors"
                >
                  {confirmSpec.confirmLabel}
                </button>
              </div>
            </div>
          </div>
        </div>,
        document.body,
      )}
    </div>
  );
};

