import React, { useMemo, useState } from 'react';
import { motion } from 'motion/react';
import { Trophy, Hourglass, ChevronRight, Sparkles, Crown } from 'lucide-react';
import { useGame } from '../../../store/GameContext';
import { SettingsManager } from '../../../services/SettingsManager';
import {
  careerWinShares,
  upcomingHOFCandidates,
} from '../../../services/playerDevelopment/hofChecker';
import type { NBAPlayer, NBATeam, RetiredJerseyRecord } from '../../../types';
import { getTeamFullName } from '../../../utils/teamNames';
import { PlayerPortrait } from '../../shared/PlayerPortrait';
import { PlayerBioView } from '../../central/view/PlayerBioView';

type Tab = 'retirees' | 'jerseys' | 'watch';

const TIER_COLORS: Record<'first_ballot' | 'regular' | 'borderline', string> = {
  first_ballot: 'bg-amber-400/15 text-amber-300 border-amber-400/30',
  regular:      'bg-sky-400/15 text-sky-300 border-sky-400/30',
  borderline:   'bg-rose-400/15 text-rose-300 border-rose-400/30',
};

const JERSEY_REASON_LABEL: Record<RetiredJerseyRecord['reason'], string> = {
  franchise_icon:     'Franchise Icon',
  championship_core:  'Championship Core',
  hof_legend:         'Hall of Fame Legend',
  loyal_star:         'Loyal Star',
  honorary:           'Honorary',
};

const JERSEY_TIER_COLORS: Record<RetiredJerseyRecord['tier'], string> = {
  automatic:  'border-amber-400/40 bg-amber-400/5',
  fast_track: 'border-emerald-400/40 bg-emerald-400/5',
  standard:   'border-sky-400/40 bg-sky-400/5',
  late_honor: 'border-zinc-500/40 bg-zinc-500/5',
};

function countAward(player: NBAPlayer, type: string): number {
  return (player.awards ?? []).filter(a => a.type === type).length;
}

function careerLine(player: NBAPlayer): string {
  const regSeasons = (player.stats ?? []).filter((s: any) => !s.playoffs && (s.gp ?? 0) > 0);
  const years = new Set(regSeasons.map((s: any) => s.season)).size;
  let pts = 0, trb = 0, ast = 0, gp = 0;
  for (const s of regSeasons as any[]) {
    pts += s.pts ?? 0;
    trb += s.trb ?? ((s.orb ?? 0) + (s.drb ?? 0));
    ast += s.ast ?? 0;
    gp  += s.gp  ?? 0;
  }
  if (gp === 0) return `${years} season${years === 1 ? '' : 's'}`;
  return `${(pts / gp).toFixed(1)} / ${(trb / gp).toFixed(1)} / ${(ast / gp).toFixed(1)} · ${years}y`;
}

export default function RetiredPlayersReviewView() {
  const { state, dispatch } = useGame();
  const [tab, setTab] = useState<Tab>('retirees');
  const [viewingPlayer, setViewingPlayer] = useState<NBAPlayer | null>(null);

  const classYear = (state.leagueStats?.year ?? new Date().getFullYear()) - 1;
  const hofThreshold = SettingsManager.getSettings().hofWSThreshold ?? 50;

  const teamsById = useMemo(() => {
    const m = new Map<number, NBATeam>();
    for (const t of state.teams ?? []) m.set(t.id, t);
    return m;
  }, [state.teams]);

  const retirees = useMemo(() => {
    return (state.players ?? [])
      .filter(p => (p as any).status === 'Retired' && p.retiredYear === classYear)
      .sort((a, b) => careerWinShares(b) - careerWinShares(a));
  }, [state.players, classYear]);

  const newJerseys = useMemo(() => {
    const out: Array<{ team: NBATeam; record: RetiredJerseyRecord }> = [];
    for (const team of state.teams ?? []) {
      const list = (team as any).retiredJerseyNumbers as RetiredJerseyRecord[] | undefined;
      if (!list) continue;
      for (const rec of list) {
        if (rec.seasonRetired === classYear) out.push({ team, record: rec });
      }
    }
    return out.sort((a, b) => {
      const order: RetiredJerseyRecord['tier'][] = ['automatic', 'fast_track', 'standard', 'late_honor'];
      return order.indexOf(a.record.tier) - order.indexOf(b.record.tier);
    });
  }, [state.teams, classYear]);

  const upcomingNext3 = useMemo(() => {
    return upcomingHOFCandidates(state.players ?? [], classYear, hofThreshold)
      .filter(c => c.yearsUntilEligible <= 3);
  }, [state.players, classYear, hofThreshold]);

  if (viewingPlayer) {
    return <PlayerBioView player={viewingPlayer} onBack={() => setViewingPlayer(null)} />;
  }

  const handleAcknowledge = () => {
    dispatch({ type: 'OFFSEASON_COMPLETE_PHASE', payload: { row: 'retiredPlayersReview' } } as any);
  };

  return (
    <div className="h-full overflow-y-auto bg-zinc-950 text-slate-100" style={{ scrollbarWidth: 'thin' }}>
      <header className="border-b border-zinc-800 bg-gradient-to-b from-zinc-900/80 to-zinc-950 px-8 pb-6 pt-10">
        <div className="mx-auto max-w-6xl">
          <span className="block text-[11px] font-bold uppercase tracking-[0.25em] text-amber-300/80">Offseason · Legacy Review</span>
          <h1 className="mt-2 font-display text-3xl font-black md:text-4xl">
            The Class That Just Walked Away
          </h1>
          <p className="mt-2 max-w-2xl text-sm text-zinc-400">
            Pay respects to {retirees.length} player{retirees.length === 1 ? '' : 's'} who retired after the {classYear} season,
            {' '}see whose number{newJerseys.length === 1 ? '' : 's'} get{newJerseys.length === 1 ? 's' : ''} raised
            to the rafters, and find out who's lining up for Springfield.
          </p>

          <div className="mt-6 flex flex-wrap gap-2">
            <TabButton active={tab === 'retirees'}  onClick={() => setTab('retirees')}  icon={<Sparkles size={14} />} label={`Retirees (${retirees.length})`} />
            <TabButton active={tab === 'jerseys'}   onClick={() => setTab('jerseys')}   icon={<Crown size={14} />}    label={`Jerseys Retired (${newJerseys.length})`} />
            <TabButton active={tab === 'watch'}     onClick={() => setTab('watch')}     icon={<Hourglass size={14} />} label={`HOF Watch (${upcomingNext3.length})`} />
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-6xl px-8 py-8">
        {tab === 'retirees' && (
          <RetireesPanel
            retirees={retirees}
            teamsById={teamsById}
            onOpen={setViewingPlayer}
          />
        )}
        {tab === 'jerseys' && (
          <JerseysPanel
            jerseys={newJerseys}
            onOpen={(playerId) => {
              const p = (state.players ?? []).find(p => p.internalId === playerId);
              if (p) setViewingPlayer(p);
            }}
          />
        )}
        {tab === 'watch' && (
          <WatchPanel
            classYear={classYear}
            upcoming={upcomingNext3}
            onOpen={setViewingPlayer}
          />
        )}
      </main>

      <footer className="sticky bottom-0 border-t border-zinc-800 bg-zinc-950/90 px-8 py-4 backdrop-blur">
        <div className="mx-auto flex max-w-6xl items-center justify-between gap-4">
          <span className="text-xs text-zinc-500">
            Once acknowledged, this step is marked complete. Calendar moves on with the rest of the offseason.
          </span>
          <button
            onClick={handleAcknowledge}
            className="inline-flex items-center gap-2 rounded-lg bg-amber-400 px-4 py-2 text-sm font-bold text-zinc-950 transition-colors hover:bg-amber-300"
          >
            Acknowledge & Continue
            <ChevronRight size={16} />
          </button>
        </div>
      </footer>
    </div>
  );
}

// ─── Sub-Panels ──────────────────────────────────────────────────────────────

function TabButton({ active, onClick, icon, label }: { active: boolean; onClick: () => void; icon: React.ReactNode; label: string }) {
  return (
    <button
      onClick={onClick}
      className={`inline-flex items-center gap-2 rounded-full border px-4 py-1.5 text-xs font-bold uppercase tracking-wider transition-colors ${
        active
          ? 'border-amber-400 bg-amber-400/10 text-amber-200'
          : 'border-zinc-800 bg-zinc-900/40 text-zinc-400 hover:border-zinc-700 hover:text-zinc-200'
      }`}
    >
      {icon}{label}
    </button>
  );
}

function RetireesPanel({
  retirees,
  teamsById,
  onOpen,
}: {
  retirees: NBAPlayer[];
  teamsById: Map<number, any>;
  onOpen: (p: NBAPlayer) => void;
}) {
  if (retirees.length === 0) {
    return <EmptyState icon={<Sparkles size={32} className="text-zinc-700" />} text="No players hung it up this season." />;
  }
  return (
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
      {retirees.map((p, i) => {
        const lastTid = lastTeamTid(p);
        const team = lastTid != null ? teamsById.get(lastTid) : undefined;
        const allStars = countAward(p, 'All-Star');
        const champs = countAward(p, 'Won Championship') + countAward(p, 'Champion');
        const mvps = countAward(p, 'Most Valuable Player');
        return (
          <motion.div
            key={p.internalId}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.03 }}
            onClick={() => onOpen(p)}
            className="group cursor-pointer overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-900/40 transition-all hover:border-amber-400/50 hover:bg-zinc-900"
          >
            <div className="flex items-start gap-3 p-4">
              <PlayerPortrait
                imgUrl={(p as any).imgURL}
                teamLogoUrl={team?.logoUrl}
                playerName={p.name}
                face={(p as any).face}
                size={56}
                ovrLabel={p.draft?.year ? String(p.draft.year) : undefined}
              />
              <div className="min-w-0 flex-1">
                <div className="truncate text-base font-bold text-slate-100 group-hover:text-amber-200">{p.name}</div>
                <div className="mt-0.5 truncate text-[11px] text-zinc-500">
                  {team ? getTeamFullName(team) : 'Free Agent'} · {(p as any).pos ?? ''}
                </div>
                <div className="mt-2 text-[11px] text-zinc-400">{careerLine(p)}</div>
              </div>
            </div>
            <div className="flex flex-wrap gap-1.5 border-t border-zinc-800/60 px-4 py-2.5">
              {mvps > 0 && <Pill text={`${mvps}× MVP`} tone="gold" />}
              {champs > 0 && <Pill text={`${champs}× Champ`} tone="emerald" />}
              {allStars > 0 && <Pill text={`${allStars}× All-Star`} tone="sky" />}
              {(p as any).farewellTour && <Pill text="Farewell Tour" tone="rose" />}
              {mvps === 0 && champs === 0 && allStars === 0 && (
                <span className="text-[10px] uppercase tracking-wider text-zinc-600">Career role player</span>
              )}
            </div>
          </motion.div>
        );
      })}
    </div>
  );
}

function JerseysPanel({
  jerseys,
  onOpen,
}: {
  jerseys: Array<{ team: NBATeam; record: RetiredJerseyRecord }>;
  onOpen: (playerId: string) => void;
}) {
  if (jerseys.length === 0) {
    return <EmptyState icon={<Crown size={32} className="text-zinc-700" />} text="No jerseys go up to the rafters this offseason." />;
  }
  return (
    <div className="grid gap-3 sm:grid-cols-2">
      {jerseys.map(({ team, record }, i) => (
        <motion.div
          key={`${team.id}-${record.number}-${record.playerId ?? record.text}`}
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: i * 0.04 }}
          onClick={() => record.playerId && onOpen(record.playerId)}
          className={`group cursor-pointer overflow-hidden rounded-2xl border p-4 transition-all hover:border-amber-400/50 ${JERSEY_TIER_COLORS[record.tier]}`}
        >
          <div className="flex items-center gap-4">
            {team.logoUrl && (
              <img
                src={team.logoUrl}
                alt={team.abbreviation ?? team.name}
                className="h-12 w-12 shrink-0 object-contain"
                loading="lazy"
              />
            )}
            <div className="min-w-0 flex-1">
              <div className="text-[11px] uppercase tracking-wider text-zinc-500">{getTeamFullName(team)}</div>
              <div className="truncate text-lg font-bold text-slate-100 group-hover:text-amber-200">
                {record.text}
              </div>
              <div className="mt-0.5 text-xs text-zinc-400">{JERSEY_REASON_LABEL[record.reason]}</div>
            </div>
            <div className="text-right">
              <div className="text-[10px] uppercase tracking-wider text-zinc-600">No.</div>
              <div className="font-display text-3xl font-black text-amber-300">{record.number}</div>
            </div>
          </div>
        </motion.div>
      ))}
    </div>
  );
}

function WatchPanel({
  classYear,
  upcoming,
  onOpen,
}: {
  classYear: number;
  upcoming: ReturnType<typeof upcomingHOFCandidates>;
  onOpen: (p: NBAPlayer) => void;
}) {
  if (upcoming.length === 0) {
    return <EmptyState icon={<Hourglass size={32} className="text-zinc-700" />} text="No Hall of Fame candidates within the next 3 seasons." />;
  }
  const byYear = new Map<number, typeof upcoming>();
  for (const c of upcoming) {
    const list = byYear.get(c.eligibleYear) ?? [];
    list.push(c);
    byYear.set(c.eligibleYear, list);
  }
  const years = [...byYear.keys()].sort((a, b) => a - b);

  return (
    <div className="grid gap-4 lg:grid-cols-3">
      {years.map((year) => {
        const candidates = byYear.get(year)!;
        return (
          <div key={year} className="rounded-2xl border border-zinc-800 bg-zinc-900/40 p-5">
            <div className="mb-1 text-[10px] uppercase tracking-[0.25em] text-zinc-500">Class of</div>
            <div className="font-display text-3xl font-black text-amber-300">{year}</div>
            <div className="mt-1 text-[11px] text-zinc-500">
              {year - classYear === 0 ? 'Eligible now' : `In ${year - classYear} season${year - classYear === 1 ? '' : 's'}`}
            </div>
            <ul className="mt-4 space-y-2">
              {candidates.map((c) => (
                <li
                  key={c.player.internalId}
                  onClick={() => onOpen(c.player)}
                  className="flex cursor-pointer items-center gap-3 rounded-lg border border-zinc-800/60 bg-zinc-950/40 p-2 transition-colors hover:border-amber-400/40 hover:bg-zinc-950"
                >
                  <PlayerPortrait
                    imgUrl={(c.player as any).imgURL}
                    playerName={c.player.name}
                    face={(c.player as any).face}
                    size={36}
                  />
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-sm font-bold text-slate-100">{c.player.name}</div>
                    <div className="mt-0.5 flex flex-wrap gap-1">
                      <span className={`rounded border px-1.5 text-[9px] font-bold uppercase tracking-wider ${TIER_COLORS[c.tier]}`}>
                        {c.tierLabel}
                      </span>
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          </div>
        );
      })}
    </div>
  );
}

function Pill({ text, tone }: { text: string; tone: 'gold' | 'emerald' | 'sky' | 'rose' }) {
  const map = {
    gold:    'bg-amber-400/15 text-amber-300',
    emerald: 'bg-emerald-400/15 text-emerald-300',
    sky:     'bg-sky-400/15 text-sky-300',
    rose:    'bg-rose-400/15 text-rose-300',
  };
  return (
    <span className={`rounded px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wider ${map[tone]}`}>
      {text}
    </span>
  );
}

function EmptyState({ icon, text }: { icon: React.ReactNode; text: string }) {
  return (
    <div className="flex flex-col items-center justify-center gap-3 rounded-2xl border border-dashed border-zinc-800 bg-zinc-900/20 py-20 text-center">
      {icon}
      <p className="text-sm italic text-zinc-500">{text}</p>
    </div>
  );
}

function lastTeamTid(p: NBAPlayer): number | null {
  const stats = (p.stats ?? []) as any[];
  for (let i = stats.length - 1; i >= 0; i--) {
    const s = stats[i];
    if (!s.playoffs && s.tid != null && s.tid >= 0 && s.tid < 100) return s.tid;
  }
  return null;
}

